(window.STORIES=window.STORIES||[]).push(...[{"n": 217, "l": "الجزء 191 | احداث السنه التاسعه من الهجرة | بين المنافقين  والمؤمنين قبل تبوك", "u": "https://www.facebook.com/groups/710210019782034/permalink/836550947147940/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وواحد_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#بين_المنافقين_والمؤمنين_قبل_تبوك\nوقفنا المرة إللي فاتت عند سؤال مهم، وهو:\nإيه المشكلة لما يكون في منافقين في الصف المسلم\nربنا بيجاوب لنا عن السؤال ده في سورة التوبة وبيقول: \n\"لو خَرَجُوا فِيكُمْ مَا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا خِلَالَكُمْ يَبْغُونَكُمُ الْفِتْنَةَ وَفِيكُمْ سَمَّاعُونَ لَهُمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ \"\nيعني لو في منافقين في الصف المسلم، المنافقين دول هيُفسدوا عليكم أمر القتال وهينشروا الشر بينكم،\nوهيمشوا بينكم بالنَّميمة بسرعة عشان يُفسدوا ذات بينِكم وينشروا الكُره والبغضاء،\nوهيبقوا عايزين يُثبِّطونكم ويخوفوكم بجيش الرومان عشان تخافوا، ويفرِّقوا كلمتكم عشان تتنازعوا وتتخانقوا وتحصل بينكم الفتنة،\nوفي منكم ناس ضعاف الإيمان هيسمعوا لهم ويطيعوهم لو خرجوا معاكم\nخلونا بقى نشوف الأحداث إللي حصلت عشان نفهم الآية كويس\nرسول الله ﷺ لما كان بيبقى عايز يخرج لغزوة كان يُوَرّي بغيرها، من التّوْرِيَة يعني،\nبمعني إنه مكنش بيقول بصراحة هو رايح فين بالضبط،\nيعني لما كان بيبقى عايز يروح مكان يتوجه لمكان تاني عكسه عشان محدش من الأعداء يعرف هو رايح فين، وبعدين يلف ويرجع للمكان إللي هو عايزه أصلا وبكده يحصل عنصر المفاجأة،\nلكن في مرتين رسول الله ﷺ قال بوضوح مكان الغزوة، الأولى كانت غزوة خيبر لأن ربنا كان وعده إنه هيفتح له حصون خيبر،\nوالغزوة التانية إللي رسول الله ﷺ أعلن عن وِجهته فيها بكل وضوح هي غزوة تبوك؛ لأن المسافة بعيدة جدا والمعركة هتكون قوية والناس محتاجة تستعد كويس للخروج\nوكان الخروج للجهاد هنا أمر واضح وواجب على كل واحد قادر يقدر يخرج للغزو،\nيعني الموضوع مكنش اختياري، زي مثلا في غزوة بدر إللي عايز يخرج يخرج وإللي مش عايز خلاص،\nلأ، الوضع هنا كان مختلف، الأمر كان واضح من رسول الله ﷺ، كل واحد يقدر يخرج للغزو يخرج\nوأرسل رسول الله ﷺ للقبائل إللي دخلت في الإسلام عشان يتجهزوا للخروج للقتال،\nو زي ما قلنا المرة إللي فاتت الوقت ده كان وقت حر وكانت الثمار على وشك إنها تبقى ناضجة ويحصدوا المحصول،\nلكن جاءت الأوامر المباشرة الصريحة من رسول الله ﷺ إن كل واحد يتجهز للخروج والجيش هيخرج بسرعة ومفيش أي تأجيل\nربنا بيقول:\n\"انفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنفُسِكُمْ فِي سَبِيلِ اللَّهِ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ\"\nلما أعلن رسول الله الأمر بالجهاد جاء المُعَذّرون من الأعراب والمنافقون يعتذروا لرسول الله، كل واحد بدأ يخترع عذر عشان مش عايزين يخرجوا،\n\"وَجَاءَ الْمُعَذِّرُونَ مِنَ الْأَعْرَابِ لِيُؤْذَنَ لَهُمْ وَقَعَدَ الَّذِينَ كَذَبُوا اللَّهَ وَرَسُولَهُ سَيُصِيبُ الَّذِينَ كَفَرُوا مِنْهُمْ عَذَابٌ أَلِيمٌ\"\nو الْمُعَذِّرُونَ من الأعراب المقصود بيها إللي عايزين يتخلّفوا عن القتال بأعذار مُفْتَعلة،\nيعني قعدوا يخترعوا أعذار عشان رسول الله ﷺ يأذن لهم في القعود وعدم الخروج للجهاد،\nفالموضوع مش زي خيبر بقى في غنائم ومكان القتال قريب، لأ، ده مكان القتال بعيد والجو الحر وفي مشقة جامدة،\nده غير انهم كانوا متوقعين إن المسلمين هيُهزموا ويتعرضوا لأذى شديد، فاحنا نعرض نفسنا للخطر ليه واحنا ممكن نعتذر بأي عذر ونقعد في المدينة\nومفيش مانع يقعدوا يحلفوا لرسول الله ﷺ إنهم يا عيني نفسهم يخرجوا بس الظروف والجوابات هي إللي منعتهم وهمّ كذابين أصلا\n شوفوا ربنا بيقول إيه عنهم:\n\"لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّاتَّبَعُوكَ وَلَٰكِن بَعُدَتْ عَلَيْهِمُ الشُّقَّةُ ۚ وَسَيَحْلِفُونَ بِاللَّهِ لَوِ اسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَاللَّهُ يَعْلَمُ إِنَّهُمْ لَكَاذِبُونَ\"\nمن المنافقين إللي جاءوا يتعذّروا لرسول الله وكان عذره خايب: الجَد بن قيس، فاكرينه\nالمنافق الوحيد إللي كان خرج مع المسلمين في عُمرة الحديبية\nجاء لرسول الله وقال له إن الناس كلها عارفة إنه لا يصبر على النساء وسهل إنه يفتن بهن، \nونساء بني الأصفر إللي هم نساء الروم شكلهم جميل وهو يا عيني من شدة ورعه وتقواه وتقويمه للأضرار اختار أخف الضررين، \nوهو إنه يتخلف عن الجهاد؛ عشان يحمي نفسه من فتنة النساء\nفقال بقى لرسول الله ﷺ إنه هيساعده بالمال قال يعني عشان يعوضه، لكن هو مش هيخرج للقتال بنفسه،\nفأعرض عنه رسول الله ﷺ وقال:\n\" أَذِنْتُ لَكَ\"\nوده ربنا فضحه في القرآن و قال عنه:\n\" وَمِنْهُمْ مَنْ يَقُولُ ائْذَنْ لِي وَلَا تَفْتِنِّي أَلَا فِي الْفِتْنَةِ سَقَطُوا وَإِنَّ جَهَنَّمَ لَمُحِيطَةٌ بِالْكَافِرِينَ\"\nيعني هو بتخلفه عن رسول الله ﷺ سقط في الشرك والإثم بسبب نفاقه ده\nوفي بقى إللي قال الدنيا حر ومش هنقدر نخرج وقعدوا يثبطوا الناس وقالوا بلاش نخرج نقاتل في الحر،\nخلونا لما الحر ده يعدّي ونقطف الثمار وبعدين نخرج،\nوده إللي ربنا قاله عنهم في سورة التوبة:\n\" وَقَالُوا لا تَنْفِرُوا فِي الْحَرِّ قُلْ نَارُ جَهَنَّمَ أَشَدُّ حَرًّا لَوْ كَانُوا يَفْقَهُونَ\"\nهمّ مش عايزين يطيعوا أمر ربنا عشان الحر؛ طب ده نار جهنم أشد حر\nيعني انتم خايفين من حر الدنيا ومش خايفين من حر جهنم إللي بخار ماء الحميم بتاعه بيخلّي الوجه يسِيح ويذوب كده من قبل حتى ما يوصل للشخص إللي هيشربه\nطيب المنافقين سكتوا بقى لحد كده\nلأ\nإيه إللي حصل؟\nرسول الله ﷺ دعا الناس لتجهيز الجيش، واتسمى الجيش ده بجيش العُسْرة بسبب قلة الأموال والزاد والبعير، \nفقال رسول الله ﷺ:\n\"من يُجهز جيش العُسرة له الجنة\"\nفكان أول واحد قام هو عثمان بن عفان رضي الله عنه، قال لرسول الله ﷺ:\n\" عليّ مائة من الإبل بأحْلاسِها وأَقتَابِها\"\nيعني عثمان بيقول لرسول الله ﷺ إنه هيتبرع لجيش المسلمين بمائة من الإبل بكااامل عدتها من سلاح وغذاء و..و..\nيعني احنا شوفنا قبل كده إللي كان بياخد مائة إبل عشان يثبت على الإسلام،\nودلوقتي احنا بنتكلم عن شخص بيدفع مائة من الإبل في سبيل الله بنفس راضية مطمئنة\nهو مش مُلزم إنه يدفع المبلغ ده كله عشان يجهز الجيش، ولا مستني حد يشجعه،\nهو حاسس إن الإسلام ده بتاعه وقضيته فعشان كده بيبذل له إللي يقدر عليه،\nولو تفتكروا احنا قلنا قبل كده إن المائة بعير تساوي خمسة مليون جنيه مصري تقريبا، يعني مش مبلغ بسيط خالص\nطبعا رسول الله ﷺ فرح جدا باللي عمله عثمان ده وظهر على أثر الفرح ده على وجهه ﷺ\nدعا رسول الله ﷺ الناس مرة تانية للإنفاق على تجهيز جيش العُسرة، فقام عثمان بن عفان رضي الله عنه مرة تانية وقال:\n\"عليّ مائة من الإبل بأحْلاسِها وأَقتَابِها\"\nدفع مرة تانية في نفس الوقت حوالي خمسة مليون جنيه \nعشان بس تتخيلوا أد إيه أجر عثمان رضي الله عنه كان عظيم، رسول الله ﷺ قال عنه:\n\" ما ضَرّ عثمان ما فعل بعد اليوم\"\nيعني الحسنات إللي جمعها عثمان رضي الله عنه وأرضاه في اليوم ده مش هيأثر فيها معصية، مفيش سيئة هتأثر على ميزان عثمان بن عفان رضي الله عنه يوم القيامة،\nو طبعا دي مش دعوة من رسول الله ﷺ لعمل السيئات و ترك عمل الطاعات والبذل في سبيل الله،\nرسول الله ﷺ لما قال الكلمة دي عارف هو قالها في حق مين، ده أفضل واحد من الصحابة بعد أبو بكر وعمر رضي الله عنهم أجمعين\nوعشان تعرفوا صدق عثمان رضي الله؛ لما رسول الله ﷺ دعا لتجهيز جيش العسرة للمرة الثالثة قام عثمان للمرة الثالثة وقال:\n\"عليّ مائة من الإبل بأحْلاسِها وأَقتَابِها\"\nمتخيلين واحد يتبرع لجيش المسلمين بحوالي خمسة عشر مليون جنيه بكل بساطة كده وهو مش مستني مقابل ولا اشترط أي شيء على رسول الله ﷺ،\nمع إنه خلاص ضمن الجنة أصلا ورسول الله ﷺ وعده بالجنة وقاله خلاص مهما عملت انت من أهل الجنة، يعني مش محتاج إنه يتصدق تاني بالمبلغ ده\nرسول الله ﷺ لما شاف إللي عثمان عمله قال:\n\" اللهم اغفر لعثمان ما أقْبَل وما أدبر، وما أخفى وما أعلن، وما أسرّ وما جَهَر\"\nتخيلوا إن في بعض الروايات بتقول إن عثمان رضي الله عنه تبرع بتسعمائة من الإبل بكامل عدتها\nودي مش أول مرة عثمان يشتري فيها الجنة، فاكرييين بئر رومة\nبئر رومة إللي رسول الله ﷺ قال عنه مَن يشتري بئر رومة وله الجنة، واشتراها عثمان رضي الله عنه بآلاف الدراهم وجعلها صدقة للمسلمين،\nطيب هل توقف عثمان عند النقطة دي وقال خلاص كده أنا ساعدت المسلمين بزيادة و رسول الله ﷺ شهد لي بالجنة فأنا كده تمام \nبعد كل ده عثمان رضي الله عنه راح لرسول الله ﷺ و نَثر في حجره ألف دينار، يعني ما يساوي حوالي ثلاثة مليون جنيه مصري \nليه عثمان رضي الله عنه يعمل كل ده ويتحمل المسئولية دي كلها لوحده؟\nلأن قلبه وعينيه على الجنة: ألا إن سلعة الله غالية، ألا إن سلعة الله الجنة\nهنا رسول الله ﷺ رفع إيده للسماء و قال:\nاللهم ارض عن عثمان ؛ فإني عنه راض\nسبحان الله، مال الدنيا كله لا يساوي الدعاء العظيم ده من رسول الله ﷺ،\nوهو الواحد يتمنى إيه غير إن ربنا يرضى عليه\nالموضوع موقفش على عثمان رضي الله عنه بس،\nعندنا أبو بكر الصديق رضي الله عنه أفضل البشر بعد الأنبياء،\nجاء لرسول الله ﷺ وأعطاه أربعة آلاف درهم،\nطبعا ممكن حد يستقل المبلغ ويقول المبلغ ده يُعتبر بسيط بالنسبة لعدد الإبل إللي قدمها عثمان بن عفان رضي الله عنه\nعارفين الأربعة آلاف درهم دول، همّ كانوا كل ما يملك أبو بكر الصديق رضي الله عنه من أموال، من الدراهم والدنانير يعني،\nورسول الله ﷺ لما شاف المال عرف إن ده كل ماله،\nفسأله ﷺ:\n\"ماذا أبقيت لأهلك؟\"\nيعني انت سيبت لأهلك إيه، فقال له أبو بكر رضي الله عنه في يقين عجيب:\n\" أبقيتُ لهم الله ورسوله\"\nهل من الممكن إن ربنا يُضيّع حد استودعناه إياه؟ \nهل يترك ربنا سبحانه وتعالى من تركناه له؟ \n مستحيل\nاحنا مؤمنين أه إن ربنا لا يضيع مَن استودعناه، لكن للأسف ده إيمان نظري عند بعض الناس محتاج يطبق ويبقى واقع عملي، زي أبو بكر كده رضي الله عنه،\n☆طبعا هنا ممكن تسألوا طيب وهو إزاي أبو بكر يتصدق  بماله كله وهو عنده زوجة وعيال، والمفروض إنهم في رقبته ولازم يكفيهم ويصرف عليهم\nالفرق بين أبو بكر رضي الله عنه وغيره من المسلمين بصفة عامة والصحابة بصفة خاصة هو شيء وَقَر في الصدر\nيعني أبو بكر كان عنده قوة يقين وتوكل على الله ملهاش حدود،\n هو عارف ومتأكد وواثق في قول رسول الله ﷺ:\n\" ثَلاثَةٌ أُقْسِمُ عَلَيهِنَّ و ذكر منها: مَا نَقَصَ مَالُ عَبدٍ مِن صَدَقَةٍ\"\nيعني المال لا ينقص أبدا إذا تصدق به المسلم، \nفأبو بكر عارف إن أمواله إللي دفعها دي موجودة عند ربنا ومش هتنقص،\nو دي مش أول مرة ينفق فيها أبو بكر كل أمواله في سبيل الله، مننساش في وقت الهجرة وفي بداية الإسلام لما كان بيشتري العبيد إللي أسلموا ويحررهم،\nفهو وصل لدرجة عالية جدا من الإيمان والصدق مع الله\nطيب هل احنا بقى مطلوب مننا نعمل زي أبو بكر كده ونتصدق بمالنا كله\nإللي يجاوبنا على السؤال ده عمر بن الخطاب رضي الله عنه \nبيقول إن اليوم إللي رسول الله ﷺ طلب فيه إن المسلمين يتصدقوا عشان يجهزوا جيش العسرة كان وَافق مال عنده كتير يقدر يتصدق منه،\nوكان دايما ينافس أبا بكر رضي الله عنه في عمل الآخرة و بيبقى عايز يسبقه، فلقى إن اليوم ده أنسب يوم يقدر يسبق فيه أبو بكر،\nفقسم ماله كله نصفين، \nنصف خلاه لأهله وعياله، والنصف الثاني أخده وراح بيه لرسول الله ﷺ،\nفلما رسول الله ﷺ شاف المال سأل عمر رضي الله عنه:\nما أبقيتَ لأهلك؟\nفقال له عمر: تركت لهم مثله\nفساعتها بقى جاء أبو بكر رضي الله عنه و أعطى رسول الله ﷺ ماله كله، فهنا قال عمر:\nوالله لا أسبقه إلى شيء أبدًا، يعني أنا عمري ما هعرف أسبقه أبدا،\nفلو أخدنا بالنا من كلام رسول الله ﷺ لما قال لكل واحد فيهم: ما أبقيتَ لأهلك، هنلاقي إن رسول الله ﷺ كان حريص على إن كل واحد فيهم يبقّي مال لأهله؛ لأن ده هو الأصل، \nأيوة التصدق بكل المال جائز لكن بشروط ومش أي حد هيقدر عليه، لكن الأَوْلى التصدق ببعض المال عشان المسلم يقدر يُؤدي الالتزامات إللي عنده\n《والموضوع فيه تفصيل كبير، إللي عايز يتوسع فيه هيلاقي الروابط في التعليقات\n》\nكل واحد من الصحابة بدأ يتصدق باللي يقدر عليه لتجهيز جيش العُسرة، سواء بقى إللي دفع أموال كتيرة زي عثمان وأبو بكر وعمر وعبد الرحمن بن عوف وغيرهم، \nوفي إللي دفع أموال قليلة على أد جهده،\nمين بقى إللي قاعد وشايف إللي بيحصل ده\nالمنافقين\n يسكتوا مثلا؟\nلأ\nشوفوا ربنا بيقول إيه عنهم:\n\" الَّذِينَ يَلْمِزُونَ الْمُطَّوِّعِينَ مِنَ الْمُؤْمِنِينَ فِي الصَّدَقَاتِ وَالَّذِينَ لَا يَجِدُونَ إِلَّا جُهْدَهُمْ فَيَسْخَرُونَ مِنْهُمْ\"\nيعني لو واحد غني من المسلمين جاء بمال قالوا:\nده بيتصدق وبينفق رياء عشان الناس تقول عليه ده مُنفق والناس تمدحه\nولو واحد فقير جاء بمال قليل بحسب قدرته سخروا منه، وسخروا من قلة عطائه واستهزءوا به: \nيعني أموالك دي يعني هي إللي هتفرق في تجهيز الجيش\nناس كده استغفر الله يعني\nواحنا بنقابل الناس دي في حياتنا وتعاملتنا، إللي هو قاعدين للساقطة واللاقطة ومفيش وراهم حاجة غير الانتقاد \nطب هل موضوع المنافقين وقف على كده؟\nلأ للأسف، لسه لهم كوارث تانية هنعرفها الجزء الجاي إن شاء الله"}, {"n": 218, "l": "الجزء 192 | احداث السنه التاسعه من الهجرة | فقراء المسلمين وجيش العُسره", "u": "https://www.facebook.com/groups/710210019782034/permalink/836551107147924/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثنان_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#فقراء_المسلمين_وجيش_العُسرة\nاتكلمنا المرة إللي فاتت عن تجهيز الصحابة لجيش العُسرة وشوفنا ردود أفعال المنافقين على صدقات الصحابة؛ سواء إللي تصدق ودفع أموال كثيرة أو إللي دفع أموال قليلة بحسب استطاعته،\nوكان من شدة فقر بعض الصحابة إن واحد منهم جاء لرسول الله ﷺ وأعطاه صاع من التمر، يعني حوالي كيلو ونص كده تمر وده إللي كان يقدر عليه\nكان في بقى ناس فقراء جدا لدرجة إنهم معندهومش حتى الكيلو ونص ده، \nزي الصحابي عُلْبَة بن زيد بن عمرو الحارثي،\nجاء لرسول الله ﷺ مع مجموعة من الصحابة عايزين يخرجوا مع الجيش للقتال وكانوا حوالي سبعة، لكن المشكلة إنهم كانوا فقراء جدا زي ما قلنا،\nفطلبوا من رسول الله ﷺ إنه يوفر لهم راحِلة يركبوا عليها عشان يخرجوا للجهاد، لكن رسول الله ﷺ مكنش عنده راحلة يحملهم عليها إلى تبوك\nفكان رد فعلهم إيه\n مقلوش بقى الحمد لله الذي عافنا من المجهود الصعب ده، واحنا كده عملنا إللي علينا\nلأ، ربنا العليم بذات الصدور بيوصف حالهم وبيقول:\n \"تَوَلَّوا وَأَعْيُنُهُمْ تَفِيضُ مِنَ الدَّمْعِ حَزَنًا أَلَّا يَجِدُوا مَا يُنفِقُونَ\"\nتخيلوا إنهم وصلوا لدرجة من الصدق في النية والشوق إلى الجهاد بالنفس والمال إنهم بكوا من الحزن إن رسول الله ﷺ  مش لاقي لهم راحلة يحملهم عليها إلى تبوك\n متخيلين شخص بيحرم من الجهاد فيبكي؛ لأنه مش قادر يجاهد في سبيل الله لا بمال ولا بنفس\nومش احنا يا جماعة إللي بنقول،\nيعني احنا ممكن يكون نشوف واحد بيبكي عشان مش قادر يعمل طاعة معينة ونفسه يعملها، \nلكن احنا مش عارفين هل هو صادقي في بكاؤه ده ولّا لأ،\nيعني البكاء ده ممكن يكون رياء، وممكن يكون حماس اللحظة ولو اتيسر له أسباب الطاعة مش هيعملها وممكن...وممكن...\nلكن إللي يعلم فعلا صدق القلب وإن البكاء ده بسبب الرغبة الحقيقية في عمل الطاعة هو ربنا\nفربنا لما قال عنهم إن بكاؤهم كان بسبب الحزن على فوات الجهاد فده يدل إنهم كانوا في أعلى درجات الصدق والتجرد والتضحية لدرجة إن ربنا خلّد ذكرهم في القرآن إللي بنتعبد بيه لله وبنختمه على الأقل مرة كل شهر وقصتهم دي بتعدّي علينا مرة في الشهر على الأقل\nوشوفوا من إكرام ربنا لهم إيه إللي حصل\nرسول الله ﷺ لما خرج بالجيش بعدين وهم ماشيين في الصحراء في الحر والتعب حوالي خمسين يوم رايح جاي، قال للصحابة بعد الغزوة وهم راجعين في طريق المدينة:\n\"إنَّ بالمدينةِ أقوامًا، ما سِرتُم مسيرًا، ولا قطعتُم واديًا إلا كانوا معكم شرَكوكم في الأجرِ\"\nيعني في المدينة مجموعة من الناس على الرغم من إنهم قاعدين في المدينة في بيوتهم في الظل ومرتاحين إلا إنهم بيشاركوكم في أجر كل حاجة بتعملوها\nفالصحابة استغربوا وقالوا:\nيا رسولَ اللهِ، وهم بالمدينةِ\n قال: وهم بالمدينةِ، حبسهُمُ العذرُ\nيعني همّ بيتمنوا وعايزين يجاهدوا بالمال؛ لكنهم لا يملكون لا درهم ولا دينار،\nعايزين يجاهدوا بأرواحهم؛ لكنهم مرضى وميقدروش يشيلوا السلاح، \nعايزين يشاركوا بأجسادهم؛ لكنهم لا يملكون راحِلة توصلهم لأرض الجهاد،\nالناس الصادقة في نيتها دي هم إللي ربنا يعذرهم ويعطيهم مثل أجر القادرين المجاهدين بأموالهم وأرواحهم، \nوهو ده العدل الإلهي فعلاً، ربنا بيعامل الناس على قدر الوسع والاستطاعة مش على حسب الأموال إللي يملكوها\n☆وفي هنا معلومة ممكن ناس كتير متعرفهاش،\nرسول الله ﷺ بيقول:\n\"إذا مرض العبد أو سافر كُتب له مثل ما كان يعمل مُقيمًا صحيحًا\" \nيعني يا جماعة لو واحد متعود على صيام الاثنين والخميس وبعدين اضطر للسفر أو جاله مرض ومحتاج ياكل وياخد دواء وفطر في يوم الاثنين والخميس فربنا بيكتب له نفس الأجر كأنه صام بالضبط\nلأنه لو مكنش حصل له الظرف ده كان هيصوم زي ما كان متعود\n◇وطبعا هنا هيطلع لنا سؤال: \nهل الحائض تاخد أجر الصيام والصلاة إذا كان متعودة عليهم\nالموضوع ده على خلاف بين العلماء لكن الراجح إنه المرأة الحائض إن شاء الله تاخد أجر الصلاة والعبادات إللي كانت بتعملها و《مداومة》 عليها في غير وقت الحيض،\nخدوا بالكم من كلمة مداومة دي، يعني هي متعودة على الصلاة ومش بتفرط فيها أبدا\nوطبعا ده لا يتعارض مع قول رسول الله ﷺ:\n ما رأيت من ناقصاتِ عقلٍ ودينٍ أغلب لِلُبّ الرجل الحازم من إحداكن،\n فقيل: يا رسول الله، ما نقصان عقلها؟\nقال: أليست شهادة المرأتين بشهادة رجل؟\nقيل: يا رسول الله، ما نقصان دينها؟ \nقال: 《أليست إذا حاضت لم تُصَلّ ولم تَصُم》\nهي أه هتاخد الأجر، لكن طبعا مش هيبقى عندها نفس قوة الإيمان إللي بتصلي وقامت بالصلاة فعلا؛ لأن إللي بيصلي بيتلذذ بالصلاة وإيمانه بيبقى أقوى، \nفأجر الصلاة نفسه يُكتب للمرأة الحائض إذا كانت مداومة على الصلاة في غير وقت الحيض،\nوطبعا يدخل في الأجر السنن وقيام الليل وغيرها من العبادات إللي المرأة كانت متعودة عليها في غير وقت الحيض\nنرجع بقى للصحابة الفقراء إللي بكوا عشان ملقوش حاجة يركبوا عليها عشان يخرجوا للجهاد، \nهم كانوا حوالي سبعة زي ما قلنا من شوية،\nواحد منهم وهو عُلْبَة بن زيد بن عمرو الحارثي \nوصل به الشوق للجهاد في سبيل الله إنه يخدم الإسلام وينصره بطريقة محدش يتخيلها ولا يتصورها أصلا\nفي الليل كده بينه وبين ربنا من غير ما حد يعرف قال:\n\"اللهم إنه ليس عندي ما أتصدقُ به،\nاللهم إني أتصدقُ على كل مسلم بكل مظلمةٍ أصابني فيها من مال أو جسد أو عِرْض\"\nيعني كأنه بيقول لربنا يارب أنا معنديش حاجة أتصدق بيها زي باقي الصحابة، \nبس أنا عايز أخد أجر الصدقة فأنا هتصدق على كل مسلم بكل مظلمة أصابني فيها من مال أو جسد أو عِرْض\nهو عايز يساعد المسلمين بأي حاجة ومش معاه حاجة يساعدهم بيها؛ يبقى خلاص يساعدهم بالعفو عن ظلمهم له ورد حسناتهم إليهم،\nيعني يوم القيامة كل واحد كان اعتدى عليه أو ظلمه أو أخد ماله بغير حق هييجي يقف قصاد ربنا يوم القيامة ويدفع له من حسناته،\nفهو بقى تصدق على المسلمين بالمظالم دي، يعني مش هياخد منهم حسنات يوم القيامة\nتاني يوم الصبح خرج مع الناس عادي للصلاة ومحدش يعرف حاجة، \nفبعد الصلاة رسول الله ﷺ قال: أين المتصدق بعِرضِه البارحة؟\nيعني فين الرجل إللي تصدق على المسلمين بعرضه امبارح؟\n فقام عُلبة رضي الله عنه من وسط الناس،\n فقال له رسول الله ﷺ:\n\"أبشر فوالذي نفسي بيده لقد كُتبتَ في الزكاةِ المُتَقبّلة\"\nهو مكنش مستني حاجة في المقابل، ولا كان متخيل إن ربنا هيخبر رسول الله ﷺ من فوق سبع سماوات بالصدقة دي، وكمان يبشره بقبول الصدقة ضمن الزكاة المتقبلة، \nيعني كان عنده كمية صدق وإخلاص أدت إن ربنا تقبل منه العمل ده،\nمع إن لو حد كان سمعه وهو بيقول كده كان ممكن يقول طيب وانت الصدقة بتاعتك دي هتفيد الجيش في إيه يعني\n لكن هو بذل إللي يقدر عليه وهو مش متخيل إن الصدقة بتاعته دي هيُضرب بيها المثل إلى يوم القيامة\n  \n☆ممكن حد يسأل ويقول: \nطيب وهو كده حقه مش هيضيع\nيعني إللي ظلموه واغتابوه دول وهو سامحهم؛ هو كده استفاد إيه؟ \nماهو خسر حسنات كان هياخدها منهم\nهو هنا مخسرش، بالعكس ده كسب حسنات ملهاش أول من آخر وربنا هو إللي هيجازيه بيها، إزاي؟\nربنا بيقول:\n\"فَمَنْ عَفَا وَأَصْلَحَ فَأَجْرُهُ عَلَى اللَّهِ\" \nواخدين بالكم من وأجره على الله دي \nيعني ربنا محددش الأجر ده هيكون أد إيه، لأن الكريم إذا أخبر بأنه يتولّى بنفسه الجزاء اقْتَضَى عِظَم قَدْر الجزاء وسِعَة العطاء،\nيعني ربنا لما يريد إنه يعطي أجر عظيم على شيء فهو بيخفي حجم الأجر ده أد إيه،\nيعني مثلا ربنا بيقول في الحديث القدسي:\n\"كل عمل ابن آدم له إلا الصيام؛ فإنه لي وأنا أجزي به\" \nفعشان ربنا يعرّفنا أد إيه أجر الصيام عظيم فهو سبحانه أخفى حجم الأجر ده،\nفالصحابي إللي تصدق بعرضه ده ربنا هيعوضه بأضعاف أضعاف الحسنات إللي كان هياخدها من إللي ظلمه أو إللي اغتابه أو..أو...\nلأن هو مهما أخد من من حسناته فالحسنات هتكون على قدر المظلمة وبس، \nيعني لو المظلمة تساوي عشرين حسنة مش هياخد أكتر من عشرين حسنة، \nبعكس تعويض ربنا العظيم له لو هو عفى في الدنيا\nوطبعا دي مش خاصة بالصحابي ده بس، ده الكلام ده لعامة المسلمين،\nيعني إللي مش لاقي أموال يتصدق بيها، يقدر يتصدق بعرضه على المسلمين وربنا هيتقبل صدقته إن شاء الله ويجازيه يوم القيامة من واسع فضله سبحانه\nبعد ما رسول الله ﷺ أعلن الخروج للجهاد اجتمع جيش عدده أكثر من ثلاثين ألف مقاتل من الصحابة في معسكر عند ثَنِيّة الوداع وهو المكان إللي هينطلق منه الجيش لتبوك،\nالمنافقين يسكتوا بقى\nرأس المنافقين عبد الله بن أبي بن سلول راح عامل معسكر هو كمان أسفل معسكر رسول الله ﷺ،\nقال يعني عشان يجمع فيه الناس\nزي كده ما عمل في غزوة أحد وكان معاه مجموعة من المنافقين خرجوا معاه وبعد كده انسحب هو والمنافقين إللي كانوا معاه وانسحب معاه ثلاثمائة من المؤمنين الصادقين بسبب تأثرهم باللي عمله ده،\nفهو عايز يعيد نفس الحركة دي تاني عشان يزعزع الجيش المسلم،\nيا ترى بقى هل هيقدر إنه يزعزع الجيش مرة تانية وينسحب ويرجع معاه حد من المسلمين؟\nده إلي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 219, "l": "الجزء 193 | احداث السنه التاسعه من الهجرة | الطريق إلى تبوك", "u": "https://www.facebook.com/groups/710210019782034/permalink/836551337147901/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثة_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#الطريق_إلى_تبوك\nوقفنا المرة إللي فاتت عند اجتماع جيش المسلمين عند ثنية الوداع عشان ينطلقوا منه لتبوك، وقلنا إن عبد الله بن أُبي بن سلول أقام معسكره أسفل معسكر رسول الله ﷺ في محاولة منه لزعزعة جيش المسلمين،\nواجتمع في معسكر عبد الله بن أبي ثمانين رجل من المنافقين، وتحرك جيش رسول الله ﷺ في اتجاه تبوك ووراهم المنافقين،\nقبل ما نعرف إللي حصل بعد كده، في رواية مشهورة في بعض كتب السيرة بتقول إن رسول الله ﷺ وصل له خبر إن المنافقين بيجتمعوا في بيت سُوَيلم اليهودي في منطقة بالمدينة اسمها \"جاسوم\" وإللي كان عايش فيها اليهود،\nوكان سبب اجتماعهم إنهم عايزين يثبطوا الناس ويصرفوهم عن الخروج مع رسول الله ﷺ لغزوة تبوك،\nفالرواية بتقول إن رسول الله ﷺ أمر طلحة بن عُبَيد الله إنه ياخد معاه مجموعة من الصحابة ويروحوا لبيت سُوَيلم اليهودي ده ويُحرّق عليهم بيت سويلم،\nوالرواية دي رواية لا تصح عن رسول الله ﷺ\nلإن الرواية دي إسنادها مُنقَطِع وفيه جَهَالة،\nيعني الإسناد مش واصل لرسول الله ﷺ وفي رواة مجهولين في الإسناد،\nو الحديث عشان يكون صحيح له شروط معينة، ومن الشروط دي إن سند الحديث يكون متصل، يعني واحد يروي عن التاني عن التالت عن الرابع لحد ما يوصلوا لرسول الله ﷺ، مينفعش كده واحد بيروي عن التاني وساب التالت والرابع ويقوم يروي عن رسول الله ﷺ بس، فلازم يكون سند الحديث متصل،\nوكمان إللي بيروِي الأحاديث دي لازم يكون معروف هو مين بالضبط مش شخص مجهول،\nيعني مينفعش حد ييجي يقول أنا سمعت كذا وكذا فنصدقه، لازم نعرف هو سمع الكلام من مين تحديدا وهل الشخص ده ينفع أصلا ناخد منه كلام ولّا لأ\nفخلاصة الكلام إن الحديث ده غير صحيح عن رسول الله ﷺ،\nوأنا قلت لكم الموضوع ده لأنها من الشُّبَه إللي أعداء الإسلام بيستخدموها للطعن في الإسلام وفي رسول الله ﷺ، بيقولوا:\nإزاي بتقولوا عن نبيكم إنه رسولُ الرحمة وكتب السيرة عندكم بتقول إنه حرّق بيت سويلم اليهودي على إللي فيه\nفاحنا بنقول إن الرواية دي لا تصح أصلا عن رسول الله ﷺ لأن إسنادها منقطع وفيه جهالة زي ما شرحنا كده، \nفخليكم فاكرين الشّبهَة والرد عليها عشان لو سمعتوا حد بيقولها تبقوا عارفين ومطمنين إن الكلام ده غير صحيح عن رسول الله ﷺ\nوأنا بس قلت لكم المختصر المفيد، \nهتلاقوا في التعليقات\n تفصيل الرد على الرواية دي وكلام العلماء فيها\nنرجع بقى لرسول الله ﷺ إللي خرج بجيش المسلمين وكان عدده أكثر من ثلاثين ألف مقاتل،\nودي أول مرة بصفة عامة يتجمع في الجزيرة العربية جيش بالعدد ده وبصفة خاصة للمسلمين،\nيعني قبل أقل من سنة كان عدد الجيش إللي فتح مكة عشر آلاف أو اثنى عشر ألف بالكتير، \nوحتى مالك بن عوف لما جمع جيش هوازن كان حوالي خمسة وعشرين ألف مقاتل،\nفدلوقتي وصل عدد جيش المسلمين لثلاثين ألف مقاتل بعد أقل من سنة واحدة من سقوط مكة\nبعد ما بدأ رسول الله ﷺ بالتحرك ناحية تبوك؛ عبد الله بن أبي بن سلول إللي كان في معسكر تاني غير معسكر رسول الله ﷺ قال للناس الوقت ده وقت حر والثمار لسه لم تنضج، فخلونا نرجع ولما نقطف الثمار والجو يتحسن نبقى نخرج نقاتل، وأنا راجع فارجعوا،\nفرجع عبد الله بن أبي ورجع معاه المنافقين وأهل الريب للمدينة،\nوأهل الريب والشك دول ناس تأثروا بكلام عبد الله بن أبي والمنافقين إللي معاه وكانوا معاهم في المعسكر بتاعهم،\nفلما رجع عبد الله بن أبي رجعوا معاه\n☆طيب مين بقى أهل الشك والريب دول\nوهل هم مختلفين عن المنافقين\nشوفوا،\nالمنافق النفاق الأكبر هو إللي بيظهر الإسلام لكنه من قلبه بيكره الإسلام وراضي بالكفر، والنفاق الأكبر ده إللي بيُخرِج من ملة الإسلام،\nو ربنا لما اتكلم عن المنافقين في سورة البقرة وهي أول سورة اتكلمت عن المنافين بالتفصيل بعد هجرة رسول الله ﷺ للمدينة؛ متكلمش سبحانه عن أشخاص بعينهم\nلأ، ده اتكلم عن أوصافهم عشان يقولنا إن المنافقين هيظهروا في كل العصور ولازم تاخدوا بالكم منهم لأنهم هم العدو الحقيقي،\nربنا بيقول عنهم:\n\"هُمُ الْعَدُوُّ فَاحْذَرْهُمْ قَاتَلَهُمُ اللَّهُ أَنَّى يُؤْفَكُونَ\"\nوربنا بيقولنا كده؛ لأنهم مش بيكونوا ظاهرين ومعروفين،\nدول بيكونوا مستخبيين وسط الناس مش متميزين بصفات ظاهرة واضحة زي التميز بين أهل الإيمان وأهل الكفر\nيعني ربنا قال في سورة البقرة عن المؤمنين:\n\"الَّذِينَ يُؤْمِنُونَ بِالْغَيْبِ وَيُقِيمُونَ الصَّلَاةَ وَمِمَّا رَزَقْنَاهُمْ يُنفِقُونَ ۩ وَالَّذِينَ يُؤْمِنُونَ بِمَا أُنزِلَ إِلَيْكَ وَمَا أُنزِلَ مِن قَبْلِكَ وَبِالْآخِرَةِ هُمْ يُوقِنُونَ\"\nوقال عن الكافرين: \n\"إِنَّ الَّذِينَ كَفَرُوا سَوَاءٌ عَلَيْهِمْ أَأَنذَرْتَهُمْ أَمْ لَمْ تُنذِرْهُمْ لَا يُؤْمِنُونَ\"\nلكن لما أتكلم عن المنافقين قال: \n\"وَمِنَ النَّاسِ مَن يَقُولُ آمَنَّا بِاللَّهِ وَبِالْيَوْمِ الْآخِرِ وَمَا هُم بِمُؤْمِنِينَ\"\nشايفين كلمة 《من الناس》 دي\nالكلمة دي بتدل على إنهم مش متميزين ولا ظاهرين وموجودين وسط الناس ومحدش بيعرفهم لأن ظاهرهم إنهم من أهل الإيمان،\nوربنا قال برده في الآية إللي شرحناها قبل كده:\n\"لَوْ خَرَجُوا فِيكُمْ مَا زَادُوكُمْ إِلَّا خَبَالًا\"\nمع إن المفروض إن الكلام يبقى لو خرجوا معكم، \nلكن ربنا قال فيكم لأن كلمة فيكم بتدل إن المنافقين كانوا منغمسين وسط المؤمنين لدرجة إن محدش يقدر يفرق بينهم\nوموضوع النفاق ده يا جماعة مش قرار الواحد بياخده مثلا ويقول أنا خلاص قررت أبقى منافق\nلأ، هو ممكن يكون مؤمن لكن يعيش على صفات النفاق الأصغر لحد ما يقع في النفاق الأكبر المُخرج من الملة والعياذ بالله،\nلدرجة إن في ناس بتبقى عايشة في النفاق وهم مش حاسين بنفسهم أصلا\n☆إزاي بقى واحد كان على الإيمان ممكن يوصل لدرجة النفاق الأكبر دي \nشوفوا،\nالإيمان والكفر في بينهم مسافة، يعني مثلا هنتخيل كده إن الإيمان على اليمين والكفر على الشمال|         | المسافة إللي بينهم دي بقى هي المسافة إللي الإنسان بيتحرك فيها إما باتجاه الإيمان أو باتجاه الكفر،\nيعني لما الأعمال الصالحة بتقل والمعاصي تزيد وبالتالي الإيمان بيضعف يبدأ الإنسان يتحرك من منطقة الإيمان إللي على اليمين باتجاه منطقة الكفر إللي على الشمال من غير ما يحس،\nفزي ما الإيمان شُعب يعني فِرق مختلفة، كذلك الكفر والنفاق همّ كمان شُعب،\nيعني مثلا الحياء شُعبة من شُعَب الإيمان وإن الواحد يشيل الأذى من الطريق برده من شُعب الإيمان،\nفكذلك النسيء من شُعب الكفر، زي ما ربنا بيقول:\n\"  إِنَّمَا النَّسِيءُ زِيَادَةٌ فِي الْكُفْرِ\"\nوكذلك الصّد عن سبيل الله من شُعب الكفر، يعني ممكن يكون واحد كافر وعايش مع نفسه كده لا بيه ولا عليه، وواحد تاني كافر وكمان بيصد عن سبيل الله زي ما ربنا قال:\n\"الَّذِينَ كَفَرُوا وَصَدُّوا عَن سَبِيلِ اللَّهِ أَضَلَّ أَعْمَالَهُمْ \"\nأما شُعب النفاق فهي زي الكذب والفجور في الخصومة وخلف الوعد وخيانة الأمانة وغيرها،\nزي ما رسول الله ﷺ قال:\nأَرْبَعٌ مَنْ كُنَّ فِيهِ كَانَ مُنَافِقًا خَالِصًا ، وَمَنْ كَانَتْ فِيهِ خَصْلَةٌ مِنْهُنَّ كَانَتْ فِيهِ خَصْلَةٌ مِنْ النِّفَاقِ حَتَّى يَدَعَهَا : \nإِذَا اؤْتُمِنَ خَانَ ، وَإِذَا حَدَّثَ كَذَبَ ، وَإِذَا عَاهَدَ غَدَرَ ، وَإِذَا خَاصَمَ فَجَرَ\"\nفشُعَب النفاق دي عبارة عن مجموعة من الأخلاق لو الإنسان عاش عليها بيفضل يبعد شوية شوية لحد ما يبقى منغمس في النفاق،\nوالدليل على إن في مسافة بين الإيمان والكفر بيتحرك فيها الإنسان، قول ربنا عن المنافقين: \n\"هُمْ لِلْكُفْرِ يَوْمَئِذٍ أَقْرَبُ مِنْهُمْ لِلْإِيمَانِ\"\nيعني همّ فضلوا يتحركوا من منطقة الإيمان لحد ما بقوا أقرب لمنطقة الكفر من منطقة الإيمان\nفالإنسان لما بيبعد عن شُعب الإيمان يبدأ ييجي مكانها شُعب النفاق:\nيكذب ويخلف الوعد وإذا خاصم فجر ويبدأ النفاق يتغلغل في القلب شوية شوية ويبدأ الشك في الدين ويضعف الإيمان وميبقاش مستقر في القلب وأي حاجة سلبية تؤثر فيه، \nويبدأ يرد الأحكام الشرعية وأوامر ربنا ولما حد يذكره بالله لا يتذكر، ويبقى من أصحاب القلوب المريضة إللي مليانة ريبة وشك، وربنا ذكرهم في القرآن قال:\n\"إِذْ يَقُولُ الْمُنَافِقُونَ وَالَّذِينَ فِي قُلُوبِهِمْ مَرَضٌ غَرَّ هَؤُلاءِ دِينُهُمْ\"\nفالمنافقون هنا المقصود بيهم المنافقين النفاق الأكبر إللي بيخرج صاحبه من الإسلام ومصيره الدرك الأسفل من النار،\nأما بقى الناس إللي في قلوبها مرض دي فهم إللي إيمانهم ضعيف وعندهم شك في موعود الله للمؤمنين\nودول ربنا بينزل عليهم الابتلاءات عشان يُظهر الأمراض المستخبية في قلوبهم دي،\nوتكون النتيجة إما إنهم ينتقلوا لمعسكر الإيمان أو ينتقلوا لمعسكر النفاق الأكبر أو معسكر الكفر والعياذ بالله، \nربنا بيقول في سورة العنكبوت:\n\"وَلَيَعْلَمَنَّ اللَّهُ الَّذِينَ آمَنُوا وَلَيَعْلَمَنَّ الْمُنَافِقِينَ\"\nيعني ربنا بيختبر الناس عشان يتبين المؤمن من المنافق\nفلما المنافقين قعدوا يقولوا بلاش نطلع نجاهد في الحر وخلونا نستنى الثمار لما تنضج ورجعوا مع عبد الله بن أُبي بن سلول رجع معاهم أهل الشك والريب زي ما قلنا،\nوابتلاءهم كان في كلام المنافقين وتأثيرهم عليهم، ربنا بيقول:\n\"وَجَعَلْنَا بَعْضَكُمْ لِبَعْضٍ فِتْنَةً\"\nفهم مصبروش وافتتنوا بالمنافقين وبدعوتهم للرجوع للمدينة ورجعوا فعلا\n☆والموقف ده بيحصل في واقعنا كتير، تلاقي بعض الناس ضعاف الإيمان بيتأثروا بكلام إللي حواليهم جدا، \nيبقوا ماشيين في طريق طاعة معين وبسبب كلام إللي حواليهم تلاقيهم رجعوا عن الطريق وتنازلوا عن الطاعة للأسف\nلما خرج جيش المسلمين من المدينة ورجع المنافقون والذين في قلوبهم مرض بعض المسلمين حزنوا إن العدد قل وهمّ محتاجين أعداد عشان يقاتلوا الروم،\nفربنا أنزل:\n\" لَوْ خَرَجُوا فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا خِلَالَكُمْ يَبْغُونَكُمُ الْفِتْنَةَ وَفِيكُمْ سَمَّاعُونَ لَهُمْ\"\nفوجود المنافقين في الصف المسلم بيتحسب بالناقص مش بالزائد يعني لو عدد الجيش ألف وخرج مع الجيش مائة من المنافقين فمش هيبقى العدد ألف ومائة،\nبالعكس ده عدد الجيش يبقى تسعمائة أو أقل، لأن المنافقين بيفتنوا الناس الموجودة وفي ناس وسط المؤمنين بيسمعوا لهم،\nفمتزعلوش إنهم تخلفوا عن الغزوة، دي مصلحة ليكم\nلما كان الجيش في منطقة اسمها الجرف في شمال غرب المدينة خرج واحد من الصحابة يلحق جيش رسول الله ﷺ، الصحابي ده هو علي بن أبي طالب،\nكان رسول الله ﷺ  مستخلفه على المدينة، \nيعني رسول الله ﷺ كان قايله يُدير شؤون المدينة في غيابه ﷺ، \nوده كان من عادة رسول الله ﷺ، يعني لما كان يخرج للغزو كان يسيب واحد من الصحابة يحكم المدينة لحد ما يرجع، زي نائب الرئيس كده،\nفجاء علي بن أبي طالب لرسول الله ﷺ وهو معاه سلاحه عايز يخرج للجهاد مع رسول الله ﷺ وقال لرسول الله ﷺ:\nيا رسول الله! أتُخَلّفَني بعدك ولم أتخَلّف عنك في غَزِاة قط\nيعني علي بيقول لرسول الله ﷺ انت هتخليني في المدينة وأنا عمري ما تخلفت عن غزوة واحدة معاك،\nفقال له رسول الله ﷺ: يا علي ...ارجع\nفقال علي رضي الله عنه:\nيا رسول الله...إن المنافقين يزعمون أنك إنما خلّفتني إلا استثقالًا بي\nيعني المنافقين ربنا ينتقم منهم على مر العصور بيقولوا إن رسول الله ﷺ ترك علي رضي الله عنه في المدينة لأنه استثقله وإنه ملوش لازمة في الجيش ومش هيفيد الجيش بشيء\nفرد عليه رسول الله ﷺ وقال له:\n\"كذبوا\nولكني خلّفتُك لما تركتُ ورائي، فارجع فاخلُفْني في أهلي وأهلِك، أفلا ترضَى يا علي أن تكون مني بمنزلة هارون من موسى، إلا أنه لا نبي بعدي\"\nيعني المنافقين دول كذابين أنا سيبتك في المدينة عشان تاخد بالك من أهلي وأهلك وأهل المدينة؛ لأن انت الشخص المناسب في الوقت ده،\nزي لما موسى ترك هارون مسؤول عن بني إسرائيل لما ذهب لميقات الله، لكن الفرق إن انت مش نبي زي هارون لأن مفيش نبي بعدي فأنا آخر الأنبياء،\nفرضي علي بن أبي طالب رضي الله عنه ورجع بسرعة للمدينة وقعد يراعي شؤون المدينة لحد ما رجع رسول الله ﷺ\nانطلق الجيش يشق الصحراء في اتجاه منطقة تبوك إللي كان بيجمع فيها الرومان،\nفي الوقت إللي كان الجيش بيتحرك في الصحراء في الحر واحد من الصحابة في المدينة.....عمل إيه\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 220, "l": "الجزء 194 | احداث السنه التاسعه من الهجرة | وصول رسول الله الي تبوك", "u": "https://www.facebook.com/groups/710210019782034/permalink/836551530481215/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعة_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#وصول_رسول_الله_لتبوك\nاتكلمنا المرة إللي فاتت عن خروج جيش المسلمين باتجاه تبوك، \nوفي الوقت ده واحد من الصحابة اسمه أبو خَيْثَمَة من الأنصار كان تخلّف عن الخروج مع رسول الله ﷺ،\nمع إنه حضر غزوة أُحد وكل الغزوات من بعد أُحد مع رسول الله ﷺ،\nبعد ما عدّى حوالي عشرة أيام على خروج الجيش؛ دخل أبو خَيْثَمَة للبستان بتاعه في يوم كان الجو حر،\nفلما دخل البستان لقى زوجتين له كل واحدة قاعدة تحت عريش ورشت مية على العريش وبردت له المية عشان يشرب وجهزت الأكل ومستنيينه ييجي،\nوالعريش معناه ما يُستظل به، يعني بيتعمل من قوائم خشبية أو حديدية والسقف بتاعه من الخوص أو جريد النخل أو...أو... بحيث إنه يظلل إللي هيقعد تحته،\nفالقعدة دي قعدة ملوكي \nمية باردة وظل وأكل وزوجتين، هيحتاج إيه أكتر من كده\nلكنه لما شاف المنظر ده قال: \n\"سبحان الله! \nرسول الله ﷺ قد غُفر لهُ ما تقدم من ذنبه وما تأخَّر في الضِّحِّ(يعني الشمس) والريح والحرِّ يحملُ سلاحَهُ على عُنُقهِ وأبو خَيْثَمَة في ظلالٍ باردةٍ، \nوطعامٍ مهيّأ، وامرأتين حَسناوينِ، ما هذا بالنَّصَفِ؛ \nوالله لا أدخلُ عريش واحدة منكما ولا أكلمكما حتى ألحق برسول الله ﷺ\"\nيعني هو بيتعجب من نفسه وبيقول إزاي يعني رسول الله ﷺ إللي ربنا غفر له ما تقدم من ذنبه وما تأخر ومع ذلك خرج في الشمس الشديدة دي وسط الريح والحر وشايل سلاحه على رقبته،\nوأنا قاعد في الظل البارد وعندي الأكل جاهز وبين امرأتين جميلتين، ده مش عدل أبدا\nفقال لهما والله ما هدخل عريش واحدة فيكم ولا هكلمكم حتى ألحق برسول الله ﷺ،\nفجهّز راحلته وانطلق فعلا يتبع جيش رسول الله ﷺ إللي كان سابقه بعشرة أيام،\nهنسيب أبا خيثمة في الطريق ونروح نشوف جيش المسلمين إللي كان ماشي في الصحراء حصل معاه إيه،\nالرحلة بالنسبة للجيش كانت صعبة وطويلة ومتعبة جدا،\nوكانوا رضي الله عنهم صابرين،\nوكان الزاد معاهم قليل، حتى إن الرجلين والثلاثة كانوا بيقسموا التمرة الواحدة بينهم\nوكان يتعاقب الرجلان والثلاثة على البعير الواحد، وكانوا بيحوّشوا الماء لأنهم كان صعب جدا يلاقوه،\nلدرجة إنهم كانوا يذبحون الإبل عشان يشربوا الماء إللي الإبل مخزناه في بطنها،\nالابتلاء كان صعب وشديد جدا\nهي غزوة تبوك دي عبارة عن سلسلة متواصلة من الابتلاءات، ويُبتلى المرء على قدر دينه\nوالموضوع موقفش لحد كده، ده ربنا ابتلاهم ابتلاء جديد عشان يختبر طاعتهم لأمر رسول الله ﷺ،\nلما وصلوا لمنطقة اسمها الحِجر لقوا فيها أبيار ماء كثير فملأوا الأوعية بتاعتهم، وبدأوا يعجنوا بالماء عشان يعملوا خبز يشبعهم بعد جوع طويل،\nوكل ده من غير ما رسول الله ﷺ يعرف ومن غير ما يستأذنوه، فلما عرف رسول الله ﷺ؛ قال:\n\"لا تشربوا من مائِها شيئاً، ولا تتوضأوا منه للصلاة،\nوما كان من عجينٍ عجنتمُوه فأعْلفُوه الإبل ولا تأكلوا منه شيئاً\"\nيعني المية إللي جمعتوها دي كُبّوها ومحدش يشرب منها خالص ولا تتوضوا منها للصلاة وأي عجين عجنتوه بالمية دي \nمحدش ياكل منه حاجة وخلّوا الإبل هي إللي تاكله\n☆طيب ليه كل ده\nمنطقة الحِجر دي يا جماعة هي المنطقة إللي كانت بها ديار ثمود قوم صالح عليه السلام، \nوقوم صالح دول ربنا أهلكهم في المنطقة دي لما كفروا بربنا وقتلوا الناقة، واحنا اتكلمنا عنهم بالتفصيل في قصص الأنبياء لو تفتكروا\nفالماء بتاعهم ده ماء غير مُبارك، فجاء الأمر الصريح والواضح من رسول الله ﷺ إن محدش يستعمل الماء ده خالص\nوعلّمهم رسول الله ﷺ يعملوا إيه لما يمرّوا على ديار الذين ظلموا أنفسهم،\nقال رسول الله ﷺ:\n\"لَا تَدْخُلُوا مَسَاكِنَ الَّذِينَ ظَلَمُوا أَنْفُسَهُمْ إِلَّا أَنْ تَكُونُوا بَاكِينَ أَنْ يُصِيبَكُمْ مَا أَصَابَهُمْ\"\nيعني لما تعدوا على مساكن ناس كانوا كفار وربنا أهلكهم تعدوا وانتم خايفين باكين متضرعين لربنا؛ عشان لا يصيبكم ما أصابهم من قسوة القلب، والإعراض، والتولّي عن الدِّين،\nومش المقصود هنا إن ربنا يُنزل العذاب العام زيهم؛\nلأن أمة الإسلام لا تُعذب بصفة عامة زي الأمم السابقة\n◇ممكن حد يقول طيب المية دي ملهاش دعوة باللي هيشرب منها\nيعني المية بيشرب منها البَرّ والفاجر، وبيشرب منه المؤمن والكافر، والجيش محتاج للماء والطريق صعب،\nده غير كده رسول الله ﷺ لما كان في مكة كان بيشرب عادي من غير ما يسأل هو ده ماء بتاع مسلمين ولّا ماء بتاع كفار،\nفإيه المشكلة يعني لما يشربوا منها\nشوفوا،\nمش كل الأوامر لازم نعرف الحكمة منها إيه، بالعكس ده في بعض الأمور ربنا بيخفي حكمتها عشان يختبر مدى طاعة عباده، وهل همّ بيعبدوا ربنا بحق ولّا بيعبدوا عقلهم والمنطق؟\nماهو في ناس كده\nمش بتنفذ أوامر ربنا غير لما تعرف الحكمة والهدف من الأمر ده عشان تقتنع وتنفذ\nفالغرض هنا كان واضح وهو اختبار الطاعة المُطلقة لرسول الله ﷺ في موقف شديد جدا زي ده\nوشوفوا ربنا بيقول إيه:\n\"وَمَا كَانَ لِمُؤْمِنٍ وَلا مُؤْمِنَةٍ إِذَا قَضَى اللَّهُ وَرَسُولُهُ أَمْرًا أَنْ يَكُونَ لَهُمُ الْخِيَرَةُ مِنْ أَمْرِهِمْ وَمَنْ يَعْصِ اللَّهَ وَرَسُولَهُ فَقَدْ ضَلَّ ضَلالًا مُبِينًا\"\nيعني ما دام ربنا أو رسوله ﷺ أمروا بشيء؛ يتنفذ على طول مفيش عندهم أي مجال للاختيار\nونجح المسلمون الصادقون في الاختبار ولم يشربوا من ماء ثمود مع شدة حاجتهم له،\nومشيوا من ديار ثمود وبعدها نزل الجيش في مكان في الطريق عشان يريّحوا،\nوالجو كان حر شديد جدا واشتد عليهم العطش لدرجة إن عمر بن الخطاب رضي الله عنه قال:\n\"أصابنا فيه عطش حتى ظننا أن رقابنا ستنقطع ..حتى أن حتى أن كان الرجل ليَذهب يلتمس الماء فلا يرجع حتى يظن أن رقبته ستنقطع\"\nيعني من شدة العطش كانوا حاسين إن رقابهم هتتقطع\nفهنا أبو بكر الصديق قال لرسول الله ﷺ:\nيا رسول الله! \nإن الله قد عَوّدك في الدعاء خيرًا فادع لنا\nيعني انت كل مرة بتدعي فيها ربنا؛ بيستجيب لك، فادعو لنا،\nفقال له رسول الله ﷺ : أتحبّ ذلك؟ \nقال أبو بكر : نعم.\nفرفع رسول الله ﷺ يده ودعا ربنا،\nومجرد ما أنزل إيده ﷺ لقوا السماء أظلمت بسبب السحاب إللي اتجمع ونزل المطر فملأوا الحاجات إللي معاهم وينفع يتخزن فيها مية،\nوراحوا يشوفوا كده هل كل المنطقة فيها مطر ولا منطقة معسكرهم بس،\nفلقوا إن المطر لم يُجاوِز المعسكر بتاعهم، يعني المطر نزل على معسكر جيش المسلمين بس\nفكانت دي معجزة من معجزات رسول الله ﷺ، والمعجزة دي زادت المؤمنين إيمانا،\nأما المنافقين إللي خرجوا مع رسول الله ﷺ وكملوا معاه في الجيش فلم تؤثر فيه أي معجزة من المعجزات\n☆هو مش المنافقين والذين في قلوبهم مرض رجعوا للمدينة\nأيوة معظم المنافقين والذين في قلوبهم مرض رجعوا للمدينة،لكن في بعض المنافقين كملّوا مع الجيش،\nوكان في واحد منهم معروف بالنفاق والصحابة عارفينه، فبعد ما حصلت معجزة المطر دي بعض الصحابة راحوا للمنافق ده وقالوا له:\nويْحَك أبَعد هذا شيء؟\nيعني كأنهم بيقولوا أظن بعد ما شفت المعجزة دي قصادك ملكش حجة إنك تفضل على النفاق والمفروض تؤمن برسول الله ﷺ\nفقال لهم:\nسحابة مَارة\nيعني مفيش معجزة ولا حاجة، ده سحابة كانت معدية فأمطرت، مش حكاية يعني\nناس قلوبها مختوم عليها والعياذ بالله،\nمهما هتشوف من آيات ومعجزات واضحة هيطلّعوا لها مبرر بأي طريقة عشان ينكروا المعجزات دي\n\"وَإِن يَرَوْا كُلَّ آيَةٍ لَّا يُؤْمِنُوا بِهَا\"\nومش بس الموقف ده إللي حصل مع المنافقين\nبعد ما سار الجيش باتجاه تبوك ونزلوا يريحوا في الطريق ناقة رسول الله ﷺ ضلّت الطريق،\nفخرج أصحاب رسول الله ﷺ يدوّروا عليها،\nوكان رسول الله ﷺ قاعد وكان قاعد معاه رجل من أصحابه اسمه عُمَارَة بن حزم، وكان عُمَارَة من السبعين إللي بايعوا بيعة العقبة الثانية، وكان من إللي حضروا غزوة بدر كمان،\nيعني مكانته عالية في الإسلام،\nوهو قاعد عند رسول الله ﷺ لقى رسول الله ﷺ بيقول:\nإن رجلًا قال: هذا محمد يُخبركم أنه نبي ويزعم أنه يخبركم بخبر السماء وهو لا يدري أين ناقته\nيعني في رجل المنافقين قال: شوفوا محمد بيقول إنه نبي وبيأتيه الخبر من السماء وهو مش عارف حتى فين الناقة بتاعته،\nفوضّح رسول الله ﷺ قاعدة مهمة قال:\n《 وإني والله ما أعلمُ إلا ما علمني الله》\nيعني رسول الله ﷺ لا يعلم الغيب ولا يعلم أي حاجة إلا إللي ربنا بيطلعه عليه\nوهنا ربنا عرّفه مكان الناقة وقال له إن الناقة موجودة في الوادي من شعب كذا وكذا، الزمام بتاعها اتعلق في شجرة  \nفمش عارفة تتحرك،\nفأمر بعض الصحابة إنهم يروحوا المكان إللي قالهم عليه عشان يجيبوا له الناقة،\nوفعلا جابوها ورجعوا لرسول الله ﷺ، كل ده وعُمَارَة بن حزم قاعد عند رسول الله ﷺ،\nفلما جاءوا بالناقة رجع عُمَارَة بن حزم لرَحْله،\nيعني المكان إللي أصحابه متجمعين فيه وبيمشوا مع بعض كمجموعة يعني وهم مسافرين،\nفلما رجع لهم قالهم:\nوالله لأعجبُ من شيءٍ حدّثناهُ رسول الله ﷺ آنفًا عن مقالةِ قائلٍ أخبرهُ الله عنه كذا وكذا\nيعني بيقولهم إن حصل شيء عجيب جدا لما كان عند رسول الله ﷺ،\nوحكى لهم قصة الرجل إللي قال الكلام وقصة الناقة،\nفواحد من إللي كانوا في رَحْل عُمَارَة ومكنش حاضر مجلس رسول الله ﷺ قال لعُمَارَة:\nابن نُصَيب والله قال هذه المقالة قبل أن تأتي\nابن نصيب ده هو يزيد بن نصيب القَيْنَقَاعي، وهو من المنافقين إللي خرجوا مع الجيش وكان طول الطريق ماشي في رَحْل عُمَارَة بن حزم،\nفلما سمع عُمَارَة الكلام قام رايح ناحية يزيد المنافق ده ودفعه بكف يده في رقبته وهو يقول:\nيا آل عباد الله إن في رَحْلِي لداهيةً وما أشعر\nأخرج أي عدو الله من رَحْلِي فلا تصحبني\nيعني:\nشوفوا يا ناس! عندي في رَحْلِي داهية ماشي معايا وأنا مش حاسس، امشي من رَحْلِي مش هسافر معاك،\nوطبعا معاه حق،\nهو مين يقدر يستحمل يصاحب واحد في السفر قال كده على رسول اللهﷺ\nالناس إللي زي كده بيبقى الحسد والعناد أكل قلوبهم واستنفذوا كل طُرق الإقناع،\nومش هينفع معاهم غير التّرك والبُعد؛ لأن مفيش فايدة منهم خلاص، ومصاحبتهم إهدار لوقت؛ غيرهم أحق بالوقت ده منهم\nوصل رسول الله ﷺ والجيش لمنطقة تبوك وخيّموا فيها، وبعد ما وصلوا شافوا ظل رجل جاي من بعيد فقال الناس: \nهذا راكبٌ على الطريق\nيعني في واحد ماشي في الطريق جاي ناحيتنا،\nفقال رسول الله ﷺ: \"كُن أبا خَيْثمةَ\"\nيعني رسول الله ﷺ يتمنى إن الشخص إللي جاي ده يكون أبو خَيْثمةَ،\nفقال الناسُ: هذا أبو خَيْثمةَ\nوأبو خَيْثمةَ إللي قلنا قصته من شوية من زوجتيه وصل دلوقتي لجيش المسلمين،\nفنزل أبو خيثمة من على بعيره واتجه لرسول الله ﷺ فسلّم عليه، فقال رسول الله ﷺ لأبي خَيْثمةَ: \n\"أَوْلَى لَكَ ياأبا خَيْثَمةَ\"\nيعني انت كدت تهلك يا أبا خيثمة بسبب تخلّفك عن جيش المسلمين،\nفحكى أبو خيثمة لرسول الله ﷺ إللي حصل معاه في المدينة وإنه ترك الظل والماء والطعام ولحق بالجيش، فدعا له رسول الله ﷺ بخير.\nإيه ده\nهو فين جيش الروم إللي المفروض كان هيقاتل رسول الله ﷺ في المنطقة دي\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 221, "l": "الجزء 195 | احداث السنه التاسعه من الهجرة | انتصار المسلمين في تبوك", "u": "https://www.facebook.com/groups/710210019782034/permalink/836551897147845/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وخمسة_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#انتصار_المسلمين_في_تبوك\nاتكلمنا المرة إللي فاتت عن وصول رسول الله ﷺ لمنطقة تبوك ونزول الجيش وتخيِيمه في المنطقة،\nوسألنا عن مكان جيش الروم إللي المفروض كان هيقاتل جيش المسلمين في منطقة تبوك،\nقبل ما نعرف إيه إللي حصل، عايزة اتكلم عن قصة مشهورة بين الناس عن أبي ذر الغفاري رضي الله عنه لكن سندها لا يصح عن رسول الله ﷺ\nطيب هو مين أبو ذر الغفاري أصلا\nأبو ذر اسمه الحقيقي جُنْدَبْ بنُ جُنادَة بن سفيان، من قبيلة غِفَار،\nاتولد قبل بعثة رسول الله ﷺ بحوالي عشرين سنة، وكان طويل ضخم وبشرته سمراء، وكان من الموحدين ولا يعبد الأصنام،\nوقبيلة غِفَار كانت مشهور بالسرقة وقطع الطريق، وكان مكانها على طريق القوافل بين اليمن والشام، \nفكانت قبيلته بتهجم على القوافل إللي بتمر في الطريق ويأخذوا أموالهم وهو كمان كان بيعمل كده وكان معروف بشجاعته في الهجوم على ااقوافل لوحده،\nفي يوم من الأيام أبو ذر وأخوه وكان اسمه أُنَيْس وأمهم خرجوا من غفار لحاجة،\nوكان الوقت ده بعد بعثة رسول الله ﷺ على طول\nوهمّ ماشيين، أُنَيس قال لأخوه أبي ذر إنه محتاج حاجة من مكة، فانت خد بالك من أمي لحد ما أرجع،\nفراح أنيس لمكة وأبو ذر مستني خارج مكة، فتأخر أنيس على أبي ذر،\nفلما جاءه سأله عن سبب تأخيره، فقال له أخوه:\nلقيت رجلًا يزعم أن الله أرسله على دينك\nيعني بيقول له إن في واحد بيقول عن نفسه إنه رسول من عند الله وبيدعو للدين إللي انت عليه إللي هو عبادة الله وحده وترك عبادة الأصنام،\nفسأله أبو ذر:\nما يقول الناس له؟ يعني الناس بيقولوا عليه إيه؟\nفقال أنيس:\nيقولون: إنه شاعر وساحر وكاهن\nوأنيس ده كان شاعر، فقال لأبي ذر:\n\"قد سمعتُ قول الكهّان، فما يقول بقولهم،\nوقد وضعتُ قوله على أَقراءِ الشعر، فوالله ما يلتئِم لسان أحدٍ أنه شعر، والله إنه لصادق، وإنهم لكاذبون\"\nيعني أنيس بيقول عن نفسه إنه سمع كلام الكهّان قبل كده، وكلام رسول الله ﷺ مش زي كلامهم خالص،\nوبيقول إنه وضع كلام رسول الله ﷺ على أوزان الشعر وبحوره ملقاش الكلام يدخل في الشعر خالص،\nوهو صادق في كلامه إنه رسول من عند الله، وهم إللي كذابين في ادعاءهم إن رسول الله ﷺ شاعر وكاهن وساحر،\nفقال أبو ذر لأخيه:\nهل أنت كافيَّ حتى أنطلقَ فأنظر؟\nيعني انت تقدر تاخد مكاني وتراعي أمنا لحد ما أروح وأشوف الموضوع بنفسي؟\nفقال له أخوه: نعم، لكن خد بالك من أهل مكة عشان محدش منهم يؤذيك؛ لأنهم كرهوه وبقوا يستقبلوه بوجه كريه\nفانطلق أبو ذر لحد ما دخل مكة،\nفقعد يدور على رجل ضعيف يسأله عن رسول الله ﷺ؛ لأنه لما يبقى ضعيف مش هيقدر يعمل حاجة لأبي ذر،\nفشاف رجل ضعيف قاعد فسأله: \nأين هذا الرجل الذي تدعونه الصّابِئ؟\nيعني هو فين الرجل إللي بتقولوا عليه إنه صابئ،\nفراح الرجل مشاور على أبي ذر وقال: الصااابئ!!\nفالناس إللي كانوا موجودين بدأوا يتلموا على أبي ذر ويضربوا فيه لحد ما أُغمى عليه\nوكأن الرجل الضعيف ده كان خدعة\nأي حد ييجي يسأله يقوم يقول كلمة الصابئ فيعرف المشركون إن الرجل ده بيسأل عن الدين الجديد فيتصرفوا معاه ويمنعوه من السماع عن الإسلام،\nفلما فاق أبو ذر وقام؛ كان غرقان دم، فتوجه ناحية زمزم فشرب من مائها وغسل عنه الدم ودخل قعد بين الكعبة وأستارها وقعد هناك حوالي ثلاثين يوم وليلة،\nومكنش في حاجة ياكلها ولا يشربها غير ماء زمزم،\nفقعد الثلاثين يوم وليلة مياكلش أي حاجة خااالص إلا إنه يشرب ماء زمزم، \nومع ذلك مكنش جعان خالص، وبالعكس ده بقى سمين لدرجة إن بطنه بقى فيها ثنيات من السّمنة\nوفي ليلة من الليالي القمر فيها كان بدر ومُضيء السماء، ربنا ألقى النوم على أهل مكة، ومكنش في حد بيطوف حول الكعبة غير امرأتين بس،\nوكان من العادة إن يكون في ناس بتطوف حول البيت، لكن الليلة دي سبحان الله مكنش في حد خالص غير المرأتين دول،\nفجاءت المرأتان ناحية أبي ذر وهما بيدعوان إساف ونائلة، الصنمين إللي مسخهما الله حجرين بعد ما زنيا عند الكعبة واتكلمنا عنهم في بداية السيرة لو تفتكروا\nالمهم يعني هو كان بيسمعهم وهم بيدعو فقال لهم باستهزاء إنهم كانا زانيين، فالمرأتين قعدوا يُوَلوِلُوا ويقولوا: أما لو كان في حد هنا من عشيرتنا\nوهم ماشيين يُوَلوِلُوا قابلهم رسول الله ﷺ ومعاه أبو بكر الصديق رضي الله عنه وكانوا نازلين من الجبل،\nفسألهما أبو بكر: مَا لَكُمَا؟\nقالتا: الصابئ بين الكعبة وأستارها\nفقالا: مَا قَالَ لَكُمَا؟\nقالتا: قال لنا كلمة تملأ الفم\nيعني قال كلمة عظيمة جدا وقبيحة في حق الآلهة منقدرش نقولها،\nفجاء رسول الله ﷺ ومعاه أبو بكر فطاف بالييت وبعدها صلى، فشافه أبو ذر وجاءه وحيّاه بتحية الإسلام،\nوكان هو أول واحد يُحَيّي رسول الله ﷺ بتحية الإسلام، فرد عليه رسول الله ﷺ:\nوعَلَيْكَ وَرَحْمَةُ اللَّهِ، مِمَّنْ أَنْتَ؟\nفقال له أبو ذر إنه من قبيلة غِفَار، فأهْوَى بيَدِهِ فَوَضَعَ أَصَابِعَهُ علَى جَبْهَتِهِ، يعني رسول الله ﷺ وضع إيده على جبهته بالطريقة دي\n \nفلما شافه ابو ذر عمل كده قال في نفسه:\nكَرِهَ أَنِ انْتَمَيْتُ إلى غِفَارٍ، يعني هو فكر إن رسول الله ﷺ محبش إنه منتمي لقبيلة غِفار، لأن القبيلة معروفة بالسرقة والسطو،\nفمد أبو ذر إيده عشان يشيل يد رسول الله ﷺ من على جبهته فمنعه أبو بكر رضي الله عنه،\nوبعدين رسول الله ﷺ رفع رأسه وسأل أبا ذر هو بقاله أد إيه في المكان ده،\nفقال له أبو ذر إنه هنا بقاله ثلاثين يوم وليلة،\nفسأله رسول الله ﷺ هو كان بياكل منين، فقال أبو ذر لرسول الله ﷺ إنه طول الفترة دي مكنش بياكل حاجة غير إنه كان بيشرب من ماء زمزم لحد ما سِمن وبطنه بقى فيها ثنيات من السمنة، ومحسش بأي جوع خلال الفترة دي،\nفقال له رسول الله ﷺ:\n\"إنَّهَا مُبَارَكَةٌ، إنَّهَا طَعَامُ طُعْمٍ\"\nمُبَارَكَةٌ يعني تظهر بركتها على إللي بيكون نيته كويسة وصادق وهو بيشربها،\nوطعامُ طُعْمٍ يعني زيها زي الطعام، إللي بيشرب منها بتشبعه وتقوّيه زي ما الطعام بيشبع ويقوّي\nفقال أبو بكر لرسول الله ﷺ إنه عايز ياخده عنده الليلة دي عشان يُطعمه،\nفراحوا لبيت أبي بكر رضي الله عنه وأكلوا وبعدها رسول الله ﷺ قال له إنه يذهب فيدعو في قومه،\nورجع أبو ذر لأخيه وأخبره إنه أسلم فأسلم معاه أخوه وأمه ورجع لقومه وقعد يدعو فيهم وأسلم نص قبيلته،\nفكان رضي الله عنه من السابقين الأولين إللي دخلوا في الإسلام،\nوبعد ما رسول الله ﷺ هاجر للمدينة أسلم النص التاني من القبيلة، وجاءوا كلهم لرسول الله ﷺ بعد غزوة أحد وقال لهم رسول الله ﷺ:\n\"غِفَارُ غَفَرَ اللَّهُ لَهَا\"\nوعاش أبو ذر في المدينة وحضر الغزوات مع رسول الله ﷺ،\nوكان أصدق الناس لسانا قال عنه رسول الله ﷺ:\n\"مَا أَقَلَّتِ الْغَبْرَاءُ، وَلَا أَظَلَّتِ الْخَضْرَاءُ، مِنْ رَجُلٍ أَصْدَقَ لَهْجَةً مِنْ أَبِي ذَرٍّ\"\nيعني محدش مشي على الأرض، ولا حد أظلّته السماء أصدق في الكلام من أبي ذر\nالقصة بقى المشهورة ولكنها في نفس الوقت قصة ضعيفة لا تصح عن رسول الله ﷺ إن رسول الله ﷺ قال عن أبي ذر :\n\" رحم الله أبا ذر ، يمشي وحده ، ويموت وحده ، ويُبعث وحده\"\nوالرواية بتقول إن لما أبو ذر خرج مع جيش المسلمين في تبوك؛ البعير بتاعه إللي كان راكب عليه بدأ يمشي بطيء وتأخر عن جيش المسلمين،\nفقالوا لرسول الله ﷺ:\nيا رسول الله ! تخلّف أبو ذر، وأبطأ به بعير\nفقال رسول الله ﷺ : دعوه ، إن يكُ فيه خير فسيُلحِقه الله بكم، وإن يكُ غير ذلك فقد أراحكم الله منه\nفنزل أبو ذر من على البعير بتاعه وشال متاعه على كتفه ومشى على رجله عشان يلحق بجيش المسلمين،\nفلما قرب من الجيش قيل لرسول الله ﷺ:\nيا رسول الله، هذا رجل يمشي على الطريق ، فقال رسول الله ﷺ : كن أبا ذر .\nفلما دققوا فيه النظر  قالوا : يا رسول الله، هو والله أبو ذر ، فقال رسول الله ﷺ : رحم الله أبا ذر، يمشي وحده ، ويموت وحده، ويُبعث وحده.\nأهه القصة دي والقول ده ضعيف لا يصح عن رسول الله ﷺ \n《هتلاقوا في التعليقات رابط من موقع الإسلام سؤال وجواب بيوضح السبب في ضعف الحديث للناس المهتمة بعلم الحديث\n》\nنرجع بقى لرسول الله ﷺ وجيش المسلمين إللي وصلوا لأرض تبوك،\nلما وصلوا حصلت المفاجأة\nجيش الدولة الرومانية إللي بتحكم وبتسيطر على نصف الأرض هرب من المنطقة لما عرفوا إن ثلاثين ألف من المسلمين جايين في جيش يقودهم رسول الله ﷺ  بنفسه\nوبكده تحقق النصر الهائل لجيوش المسلمين\nإيه إللي خلّاهم يهربوا مع إنهم جيش الدولة الأولى في العالم ومهاراتهم عالية في القتال ده غير قوة الأسلحة إللي عندهم بالنسبة لأسلحة المسلمين\nبكل بساطة:\n\" سَنُلْقِي فِي قُلُوبِ الَّذِينَ كَفَرُوا الرُّعْبَ بِمَا أَشْرَكُوا\"\nورسول الله ﷺ قال:\n\"نصرتُ بالرعب مسيرةَ شهر\"\nلما الرومان عرفوا إن في جيش من ثلاثين ألف جايين افتكروا إللي حصل لهم في مؤتة والمسلمين كانوا ثلاثة آلاف فقط وهمّ كانوا مائتين ألف،\nفإيه بقى إللي هيحصل لهم والمسلمين ثلاثين ألف وكمان معاهم رسول الله ﷺ\nفكان بالنسبة لهم قرار الهروب ده في حد ذاته غنيمة حتى ولو سقطت هيبة الدولة الرومانية بسبب هروبهم ده\nورسول الله ﷺ لم يكتفِ بالنجاح المُبهِر ده وقرر إنه يرجع للمدينة؛ لأ، \nده قعد في أرض تبوك حوالي عشرين يوم \nعشان يثبت للجميع إنه مش خائف من الرومان وأعوان الرومان من القبائل النصرانية العربية الموجودة في منطقة شمال الجزيرة العربية ومنطقة الشام،\nمع إن كان من عادة الجيوش في الزمن ده إنهم يقعدوا في أرض الموقعة ثلاثة أيام فقط؛\nلكن رسول الله ﷺ قعد المدة الطويلة دي لإثبات قوة الدولة الإسلامية وجيش المسلمين وعدم الرهبة من جيوش الرومان\nومش بس كده، ده رسول الله ﷺ أرسل سرية بقيادة خالد بن الوليد رضي الله عنه ومعاه أربعمائة وعشرين فارس\nإلى دَوْمَة الجَنْدل إللي كانت على بُعد ثلاثمائة كيلو من منطقة تبوك،\nوكان زعيم دَوْمَة الجَنْدل اسمه أُكَيْدِر بن عبد الملك الكِنْدي،\nوكان أُكَيْدِر زعيم من زعماء النصارى إللي كانوا بيحكموا منطقة واسعة في شمال الجزيرة، وكان بيساعد الرومان في حربهم ضد المسلمين،\nفأسره خالد رضي الله عنه ورجع به لرسول الله ﷺ،\nوبعد حوار دار بين رسول الله ﷺ وبين أُكَيْدِر، أقرّه رسول الله ﷺ على ملكه في مقابل إنه يدفع الجزية،\nولما سمع الناس عن إللي حصل مع أُكَيْدِر وهروب جيش الرومان من المسلمين؛ جاء ملوك وأمراء مدن الشام المجاورة  للجزيرة العربية، عشان يصالحوا رسول الله ﷺ على الجزية،\nوكان هِرقل في الوقت ده في بيت المقدس، وكان رسول الله ﷺ عايز يرسل له رسالة تانية غير إللي كان أرسلها مع دحية الكلبي،\nفقال رسول الله ﷺ مين ياخد رسالتي ويوصلها لقيصر وله الجنة،\nفقام واحد من المسلمين وسأل رسول الله ﷺ: \nوإن لم أُقتل؟\nيعني حتى لو وصلت الرسالة من غير ما أُقتل هيكون جزائي الجنة، فقال له رسول الله ﷺ:\nوإن لم تُقتل\nيا ترى الصحابي قدر يوصل رسالة رسول الله ﷺ بدون ما يقتل، ولّا قُتل؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 222, "l": "الجزء 196 | احداث السنه التاسعه من الهجرة | اهم الاحداث في منطقة تبوك", "u": "https://www.facebook.com/groups/710210019782034/permalink/836552177147817/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستة_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#أهم_الأحداث_في_منطقة_تبوك\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما قال مين ياخد رسالتي ويوصلها لقيصر وله الجنة،\nفقام واحد من المسلمين وسأل رسول الله ﷺ: \nوإن لم أُقتل؟ فقال له رسول الله ﷺ:\nوإن لم تُقتل\nفانطلق الصحابي ومعاه الرسالة وتوجه لبيت المقدس إللي كان هرقل بيزوره ساعتها وبعدها كان هيرجع للقسطنطينية عاصمة الدولة الرومانية، \nفكانوا فارشين الأرض ببُساط محدش يمشي عليه غير قيصر، والبساط ده حاجة زي السجاد الأحمر إللي بيفرشوه للرؤساء عشان يمشوا عليه في زماننا دلوقتي كده\nالمهم، الصحابي رمى الرسالة من بعيد على البساط ده واستخبى وقعد يراقب الموقف،\nفلما وصل قيصر إلى لمكان الرسالة الموجودة على البساط  أخذها واستدعى رئيس القساوسة وأعطاه الرسالة وخلاه يقرأها عشان يفهّمه إللي فيها، فقال له:\nما علمي في هذا الكتاب إلا كعِلمِك\nيعني علمي علمك أنا مش عارف الرسالة دي فيها إيه،\nفنادى قيصر: مَنْ صاحب الكتاب فهو آمن؟\nيعني هرقل نادى على الشخص إللي ألقى الرسالة وقاله لو أظهر نفسه فهو آمن ومحدش هيمسه بسوء،\nفخرج الصحابي لهرقل، فقال هرقل:\nإذا أنا قدمتُ فَأْتني\nيعني لما أرجع من بيت المقدس تعال لي في القصر بتاعي، فلما رجع قيصر جاءه الصحابي،\nفأمر قيصر بإغلاق أبواب قصره وبعدين أمر منادي ينادي:\nأَلَا إن قيصر قد اتبع محمدًا وترك النصرانية!\nفتجمع الجنود ومعاهم السلاح وحاصروا قصر هرقل\nفقال هرقل للصحابي:\nقَدْ ترى أني خائف على مملكتي \nيعني انت شايف إللي حصل أهه ومملكتي هتضيع لو أنا اتبعت محمد ﷺ،\nوبعدها أمر هرقل المنادي ينادي مرة تانية:\nأَلا إن قيصر قد رضي عنكم وإنما اختبركم لينظُر كيف صبركم على دينكم فارجعوا\nيعني قيصر كان عايز يختبركم ويشوفكم متمسكين بدينكم ولّا لأ عشان كده قال الكلام إللي قاله ده،\nفلما لقاكم متمسكين خلاص هو بقى مبسوط منكم فكل واحد بقى يرجع لمكانه خلاص،\nوفعلا رجع الجنود لمكانهم، وكتب قيصر لرسول الله ﷺ رسالة قال له فيها إنه مسلم، وأرسل لرسول الله ﷺ دنانير مع الرسالة، فلما قرأها رسول الله ﷺ قال:\nكذبَ عدو الله ليس بمسلمٍ وهو على النصرانية\nوقسّم رسول الله ﷺ الدنانير في الجيش.\nوفعلا مات هرقل في الآخر على النصرانية\nقلنا بقى إن رسول الله ﷺ قعد حوالي عشرين يوم في منطقة تبوك،\nخلال العشرين يوم دول، حصلت شوية أحداث، من الأحداث دي إن رسول الله ﷺ قال لعوف بن مالك حديث:\nأُعدُدْ ستًّا بين يدي الساعةِ : \nمَوتي ؛\nثم فتحُ بيتِ المقدسِ ،\nثم مُوتانِ يأخذ فيكم كقُعاصِ الغنمِ ،\nثم استفاضةُ المالِ حتى يُعطَى الرجلُ مائةَ دينارٍ ، فيظلُ ساخطًا ،\nثم فتنةٌ لا يبقى بيتٌ من العربِ إلا دخلَتْه ، \nثم هُدنةٌ تكون بينكم وبين بني الأصفرِ ، فيغْدرون ، فيأتونكم تحت ثمانينَ غايةً ، تحت كلِّ غايةٍ اثنا عشرَ ألفًا\"\nوطبعا احنا اتكلمنا عنهم بالتفصيل في علامات الساعة، بس حبيت أفكركم بإن الحديث ده كان في غزوة تبوك\nمن الأحداث إللي حصلت برده إن رسول الله ﷺ كان قاعد وسط الصحابة فسألهم:\nما فَعَلَ كعْبُ بْنُ مَالكٍ؟ \nيعني هو فين كعب بن مالك مخرجش معانا ليه، وكعب بن مالك ده من الصحابة إللي بايعوا بيعة العقبة الثانية،\nوإللي لما أسلم ورسول الله ﷺ عرف اسمه قال :\nالشاعر!!!\nوحضر مع رسول الله ﷺ الغزوات ومتخلفش عن رسول الله ﷺ قبل كده، ما عدا بس غزوة بدر لأن محدش كان يعرف إن هيحصل قتال أصلا،\nوكان رضي الله عنه من الناس إللي ثبتت يوم أُحد،\nفهو حد له وزنه في الإسلام، لكنه محضرش الغزوة دي،\nفدي أول مرة رسول الله ﷺ يسأل عنه في الموقف ده،\nفقالَ رَجُلٌ مِن بَنِي سلمِة:\nيا رَسُولَ اللهِ حَبَسَهُ بُرْدَاهُ، وَالنَّظرُ في عِطْفيْه\nيعني لأن كعب كان رجلا أميرا، وانتم عارفين عادة الأمراء إنهم لما بيلبسوا ملابس حلوة بيتكبروا وينشغلوا بالنظر فيها،\nفهو بيقول إن كعب زي الأمراء المتكبرين إللي بتشغلهم الدنيا\nفَقال لَهُ مُعَاذُ بْنُ جَبَلٍ:\nبِئس مَا قُلْتَ\nوَاللَّهِ يا رَسُولَ اللهِ مَا عَلِمْنَا علَيْهِ إِلاَّ خَيْراً\nيعني هو دافع عن عِرض كعب بن مالك رضي الله عنه والتمس له العذر، فَسكَت رَسُولُ اللهِ ﷺ.\n◇طيب هو ليه أصلا كعب بن مالك محضرش الغزوة دي وتخلّف عن الخروج\nقصة كعب بن مالك هنتكلم عنها كاملة إن شاء الله بعد ما رسول الله ﷺ يرجع للمدينة\nمن الأحداث برده إللي حصلت إن رسول الله ﷺ مرة خرج لقضاء حاجته في مكان بعيد، وكان معاه واحد من الصحابة،\nفبعد ما انتهى من قضاء الحاجة الصحابي صب على رسول الله ﷺ الماء عشان يتوضأ،\nوتأخر رسول الله ﷺ على المسلمين، فقدّموا عبد الرحمن بن عوف رضي الله عنه عشان يصلي بهم،\nفجاء رسول الله ﷺ بعد ما كان عبد الرحمن بن عوف صلى الركعة الأولى، فصلى رسول الله ﷺ مع الصحابة مأموما الركعة الثانية،\nفلما سلم عبد الرحمن بن عوف من الصلاة قام رسول الله ﷺ وصلى الركعة إللي فاتته،\nففزِع المسلمون لأنَّهم سبَقوا النَّبي ﷺ بالصَّلاة، وقعدوا يسبحوا، \nفلما سلم رسول الله ﷺ من الصلاة قال لَهُم: قد أصبتُمْ\nيعني إللي انتم عملتوه ده كان صح، \nيعني انهم يصلوا مادام رسول الله ﷺ اتأخر عليهم، وإنهم يقيموا الصلاة في ميعادها أَوْلى وأحسن من إنهم يستنوا رسول الله ﷺ.\nمن المواقف إللي حصلت في غزوة تبوك كمان:\n واحد من الصحابة اسمه يَعْلَى بنُ أُمَيَّةَ رضِي اللهُ عنه بيقول إنه استأجر أَجير عشان يخدمه في الغزوة،\nفالأجير ده اتخانق مع واحد تاني فراح الأجير عضّ الرجل من ذراعه\nفالرجل المعضوض شد إيده من فم الأجير إللي بيعضه ده بقوة فانخلعت إحدى ثَنِيَّتَيْهِ،\nيعني من قوة نزع الرجل يده من فم الأجير إللي بيعضه خلع له سِنة من أسنانه،\nفراحوا لرسول الله ﷺ وحكوا له إللي حصل، فلم يُوجِب رسول الله ﷺ للرجل إللي انخلعت سنته ده دِيَة أو قصاص،\nمع إن ربنا بيقول:\n\" وَكَتَبْنَا عَلَيْهِمْ فِيهَا أَنَّ النَّفْسَ بِالنَّفْسِ وَالْعَيْنَ بِالْعَيْنِ وَالْأَنفَ بِالْأَنفِ وَالْأُذُنَ بِالْأُذُنِ وَالسِّنَّ بِالسِّنِّ وَالْجُرُوحَ قِصَاصٌ\"\nيعني لو حد كسر سن حد فالجزاء إما القصاص سن قصاد سن، أو يكون في دِية\nلكن هنا رسول الله ﷺ لم يوجب له أي شيء؛ وقال له:\n\"أفَيَدَعُ يَدَهُ في فِيكَ تَقْضَمُهَا، كَأنَّهَا في فِي فَحْلٍ يَقْضَمُهَا\"\nيعني بيقوله كنت عايزه يعني يسيب إيده في فمك تقعد تقطم فيها كأنها في فَمِ ذَكَرِ إِبِلٍ يَأكُلها\nفالرجل الأجير ده هو إللي غلطان من الأول وكان السبب في انخلاع سنته، والرجل الثاني كان بيدافع عن نفسه، فبالتالي ملوش دية ولا قصاص\nولو خدتوا بالكم رسول الله ﷺ بيشبه إللي الأجير عمله ده بفِعلِ الحيوانِ الذي لا يَعقِل؛ عشان ينفّر الناس عن مِثل الفعل ده\nإن شاء الله هنكمل باقي الأحداث الجزء الجاي.\nمعلش الجزء ده صغير بس عندي ظروف ومحبتش إني أعتذر عن جزء النهاردة\n☆"}, {"n": 223, "l": "الجزء 197 | احداث السنه التاسعه من الهجرة | العوده الى المدينه", "u": "https://www.facebook.com/groups/710210019782034/permalink/836552387147796/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#العودة_إلى_المدينة\nهنكمل إن شاء الله باقي الأحداث إللي حصلت خلال العشرين يوم إللي قعدها رسول الله ﷺ في منطقة تبوك،\nلما وصل رسول الله ﷺ لمنطقة تبوك قالهم إن هتيجي رياح شديدة الليلة دي فمحدش يخرج في الريح دي،\nوإللي عنده بعير يربطه كويس،\nففعلا هبت ريح شديدة فخرج في الريح رجل فحملته الريح ورمته في جبل طَيْء ومات طبعا\nسبحان الله في كل زمن كده، لازم حد يطلع ويخالف التحذيرات إللي بتُعلن\nوالنتيجة زي مانتم شايفين موت وهلاك\nوطبعا دي كانت من معجزات رسول الله ﷺ، يعني ربنا أطلعه على الغيب وإن في رياح شديدة هتهب في الليلة دي\nومن الأحداث إللي حصلت برده إن الصحابة أصابتهم مجاعة، يعني كانوا جعانين ومفيش حاجة ياكلوها،\nفقالوا: \"يا رسول الله، لو أَذِنتَ لنا فنَحَرنا نَوَاضِحَنا فأكلنا وادَّهنا\"\nيعني هم بيطلبوا من رسول الله ﷺ إنهم يذبحوا الجمال بتاعتهم عشان ياكلوا منها وياخدوا دهونها يستعملوه،\nفرسول الله ﷺ قال لهم :\nافعلوا\nفهو أذن لهم من باب الرأفة والشفقة عليهم لأنهم كانوا مُجهَدين وتعبانين،\nفجاء عمر بن الخطاب رضي الله عنه وقال لرسول الله ﷺ:\n\"يا رسول الله، إن فعلتَ قَلّ الظَّهر، \nولكن ادعُهم بفَضْل أَزْوَادِهم، ثم ادعُ الله لهم عليها بالبركة، لعل الله أن يجعل في ذلك البركة\"\nيعني عمر بيقول لرسول الله ﷺ إن الناس لو ذبحوا الجِمال كده عدد الجمال هيقل ومش هيلاقوا حاجة يركبوها والطريق للمدينة طويل\nفاقترح عمر رضي الله عنه على رسول الله ﷺ إنه يجمع من الناس بواقي الأكل إللي عندهم ورسول الله ﷺ يدعو الله إنه يبارك لهم في الطعام الموجود، ولما ربنا يبارك فيه الأكل هيكفيهم،\nفقال رسول الله ﷺ: \nنعم، فدعا بنَطَع فبَسطه، ثم دعا بفضل أزْوَادهم، فجعل الرجل يَجِيء بكفِّ ذُرة ويجيء بكف تمر ويجيء الآخر بكسرة حتى اجتمع على النِّطْع من ذلك شيء يسير.\nيعني رسول الله ﷺ وافق وطلب منهم يجيبوا نَطَع، والنِّطْع ده عبارة عن بساط من الجلد بيوضع عليه الطعام، زي أكياس السفرة إللي بناكل عليها في زمننا دلوقتي كده تقريبا،\nففرشوا البساط وقال لكل واحد يجيب الطعام الباقي عندهم،\nفواحد جاء بملئ كفه ذرة والتاني جاء بملئ كفه تمر وإللي عنده بقايا كسرات عيش جاء بها لحد ما اجتمع على البساط بعض الطعام،\nفدعا رسول الله ﷺ بالبركة، ثم قال: \n\"خذوا في أَوْعِيَتِكم\"\nفأخذوا في أَوْعِيَتِهم حتى ما تركوا في العسكر وعاء إلا ملأوه وأكلوا حتى شبعوا وفضل فضلة.\nيعني رسول الله ﷺ قالهم ياخدوا من الطعام إللي على البساط ويملوا الأوعية بتاعتهم فملأوا كل الأوعية إللي في المعسكر وأكلوا لحد ما شبعوا وكمان اتبقى شوية من الطعام،\nودي معجزة تانية لرسول الله ﷺ\nوهنا قال رسول الله ﷺ:\nأشهد أن لا إله إلا الله وأني رسول الله، لا يَلقى الله بهما عبد غير شاكٍّ فيُحجَب عن الجنة\nوالحديث معناه إن إللي يموت على التوحيد فإن مآله ونهايته إلى الجنة، حتى لو عُذِّب في النار فترة فهو هيخرج منها ويُخلّد في الجنة.\nكل المعجزات إللي حصلت في أرض تبوك دي كانت سبب في طمأنة قلوب المُؤلفة قلوبهم ومُسلمي الفتح ومسلمي حنين وغيرهم\nبعد ما أقام رسول الله ﷺ في أرض تبوك عشرين يوم؛ قال أبو هريرة رضي الله عنه إن رسول الله ﷺ قام فيهم خطيبا   فحمد الله تعالى وأثنى عليه ثم قال:\nإن الله أَذِن لكم بهذا المسير وقد أَذِن لكم بالرجوع، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ ، لَوْلَا أَنْ يَشُقَّ عَلَى الْمُسْلِمِينَ مَا قَعَدْتُ خِلَافَ سَرِيَّةٍ تَغْزُو فِي سَبِيلِ اللَّهِ أَبَدًا، \nوَلَكِنْ لَا أَجِدُ سَعَةً فَأَحْمِلَهُمْ ، وَلَا يَجِدُونَ سَعَةً ، وَيَشُقُّ عَلَيْهِمْ أَنْ يَتَخَلَّفُوا عَنِّي، \nوَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ ، لَوَدِدْتُ أَنِّي أَغْزُو فِي سَبِيلِ اللَّهِ فَأُقْتَلُ ، ثُمَّ أَغْزُو فَأُقْتَلُ ، ثُمَّ أَغْزُو فَأُقْتَلُ\"\nيعني رسول الله ﷺ بيقولهم إن خلاص كده الغزوة خلصت وربنا أَذن لهم بالرجوع للمدينة،\nوكمان هنا بيوضح لهم نقطة مهمة وهي إنه نفسه يخرج في كل سرية بتخرج للقتال في سبيل الله من كتر حبه للجهاد ﷺ وإنه نفسه يغزو في سبيل الله ويُقتل وبعدين يُبعث مرة ثانية فيغزو في سبيل فيُقتل وهكذا،\nلكن هو ميقدرش يخرج في كل السرايا لأن ده هيبقى في مشقة على المسلمين، طب ليه\nلأن الكثير منهم فقراء، لا يملكون ما ينفقون على أنفسهم في السفر، \nولا يجدون دابة تحملهم إلى المسافات البعيدة، ولا يملك رسول الله ﷺ وأغنياء الصحابة المال اللازم لخروجهم للقتال.\n☆طيب وهو ليه أصلا لازم على المسلمين إنهم يخرجوا مع رسول الله ﷺ \nلسببين:\n◇الأول:\nإنهم من داخل نفوسهم بيحبوه ﷺ حب أعلى من حبهم لأنفسهم، ويفدونه بأرواحهم، فخُوفهم عليه بيخليهم مش عايزين يتخلفوا عنه\n◇السبب الثاني: قول ربنا:\n\"مَا كَانَ لِأَهْلِ الْمَدِينَةِ وَمَنْ حَوْلَهُمْ مِنَ الْأَعْرَابِ أَنْ يَتَخَلَّفُوا عَنْ رَسُولِ اللَّهِ وَلَا يَرْغَبُوا بِأَنْفُسِهِمْ عَنْ نَفْسِهِ\"\nيعني ربنا بيقول إن مينفعش أهل المدينة ولا الناس إللي حولها من الأعراب إنهم يتخلفوا عن الخروج للغزو مع رسول الله ﷺ، ومينفعش رسول الله ﷺ يبقى بيعاني مشقة السفر والتعب والجهاد وهمّ قاعدين في بيوتهم مرتاحين من غير أي تعب ولا مشقة\nبعد الخطبة إللي رسول الله ﷺ خطبها دي، \nالناس بدأت تستعد للعودة للمدينة وبعدها تحرك الجيش باتجاه المدينة،\nخلال الطريق والجو حر الناس تفرقت كل واحد ماشي في طريقه، \nفمعاذ بن جبل رضي الله عنه لقى نفسه أقرب الناس إلى رسول الله ﷺ في الطريق فلقى إنها فرصة لا يمكن تفويتها، فقرّب منه وبدأ يتكلم معاه، فسأله معاذ:\nيا رسولَ اللهِ، أخبِرْني بعملٍ يُدخِلُني الجنَّةَ ويُباعِدَني عن النار!\nيعني بيسأل رسول الله ﷺ عن عمل لو عمله يكون سبب في دخوله للجنة ونجاته من النار،\nتخيلوا إن إللي بيسأل ده هو إمام العلماء يوم القيامة وأعلم الأمة بالحلال والحرام وكان من أوائل الناس إللي أسلموا في المدينة\nفما بالكم بينا احنا إللي محتاجين الكلام ده أكثر من أي حد \nرسول الله ﷺ قال له:\n\"لَقَدْ سَأَلْتَ عَنْ عَظِيمٍ وَإِنَّهُ لَيَسِيرٌ عَلَى مَنْ يَسَّرَهُ اللَّهُ عَلَيْهِ\"\nيعني رسول الله ﷺ بيقوله انت سألت عن حاجة فعلها عظيم\nعلى النُّفوسِ، أو سأَلتَني عن شَيءٍ هو نفسه عَظيمٍ؛ \nلأنَّ دُخولَ الجنَّةِ والبُعدَ عَن النَّارِ محتاج إن الإنسان يعمل كلِّ عمَلٍ مأمورٍ بفِعْلِه واجتِنابَ كلِّ عمَلٍ مَنهيٍّ عن فِعلِه،\nومع عِظَمِ العمَلِ ده إلَّا إنه سَهلٌ وهيِّنٌ على إللي ربنا بيعينه عليه.\nبدأ رسول الله ﷺ يقول لمعاذ رضي الله عن إيه العمل العظيم إللي يدخله الجنة وينجيه من النار، قال:\n\"تَعْبُدُ اللَّهَ وَلَا تُشْرِكْ بِهِ شَيْئًا،《وهو توحيد الله وإفراده بالعبادة》 \nوَتُقِيمُ الصَّلَاةَ،《يعني يقيمها في أوقاتِها تامَّةَ الأركانِ والوَاجباتِ》\n وَتُؤْتِي الزَّكَاةَ،《يعني تُخرج الزكاةَ مِن مالك بشُروطِها لو كنتُ غنيًّا وتَملِكُ النِّصابَ》\nوَتَصُومُ رَمَضَانَ،《يعني تصومُ الشَّهرَ المفروض صيامُه على المستطيعِ القادِرِ بشُروطِه》\nوَتَحُجُّ الْبَيْتَ 《يعني تَقصِدُ البَيتَ الحرامَ والكعبةَ وتؤدِّي مَناسِكَ الحجِّ بأركانِها وبشُروطِها وأحكامِها》\nيعني باختصار: إللي عايز يدخل الجنة ويبعد عن النار يقيم أركان الإسلام الخمسة\n☆طيب يا جماعة إزاي هنقيم أركان الإسلام من غير ما نتعلم\nلازم نتعلم يعني إيه نعبد الله ولا نشرك بيه شيء، متخيلين إن احنا لو حبينا حد أكثر من ربنا يبقى احنا كده أشركنا في المحبة؟\nوكده بقى في خلل في كلمة التوحيد واحنا مش حاسين\nعشان كده لازم نتعلم عن ربنا وصفاته ونملأ قلوبنا بحبه عشان محدش يبقى أحب لينا من ربنا\nوطبعا الكلام برده ينطبق على إننا نتعلم الصلاة الصحيحة زي ما رسول الله ﷺ كان بيصلي؛ لأن رسول الله ﷺ قال: \nصلوا كما رأيتموني أصلي.\nوكمان محتاجين نتعلم متى تجب الزكاة وعلى مين وإيه مقدارها، \nومحتاجين نتعلم أحكام الصيام وإزاي نصوم صح وميبقاش أفعالنا وأخلاقنا وكلامنا في اليوم إللي بنصومه زي اليوم أفعالنا وأقوالنا في اليوم إللي مش بنكون صايمينه،\nوكمان محتاجين نعرف ونتعلم أحكام الحج وإلا إزاي هنعرف متى نُحرم ومتى نتَحلل من الإحرام وإيه المطلوب مننا في وقت الحج بالضبط،\nشوفتوا الموضوع مش بسيط إزاي ومحتاج مجهود وعلم وصبر\nيعني زي ما رسول الله ﷺ قال لمعاذ: لَقَدْ سَأَلْتَ عَنْ عَظِيمٍ، الموضوع فعلا مش سهل، لكنه إللي يصبر ويتعلم ويجاهد نفسه ربنا هييسرله تطبيق الأعمال إللي رسول الله ﷺ قالها لمعاذ رضي الله عنه \nرسول الله ﷺ موقفش عند الخمس أعمال دول، ده زاد معاذ رضي الله عنه وقال له:\n\"أَلَا أَدُلُّكَ عَلَى أَبْوَابِ الْخَيْرِ\"\nيعني خليني أرشدك  على طرق الخير ومفاتيحه الموصلة له وهو النجاح في الدنيا والنعيم في الآخرة ، قال:\n\"الصَّوْمُ جُنَّةٌ، وَالصَّدَقَةُ تُطْفِئُ الْخَطِيئَةَ كَمَا يُطْفِئُ الْمَاءُ النَّارَ، وَصَلَاةُ الرَّجُلِ فِي جَوْفِ اللَّيْلِ\"\n◇الصَّوْمُ جُنَّةٌ معناه إن الصيام سِترٌ وحِفظ لصاحبِه مِن الشَّهواتِ في الدُّنيا، ومِن النَّارِ في الآخِرةِ، زي كده إللي بيكون معاه درع بيحمي بيه نفسه في المعركة،\nوالمقصود بالصيام هنا هو صيام التطوع؛ لأن رسول الله ﷺ ذكر خلاص صيام الفرض في البداية،\n◇والصدقة تُكفر السيئات وتمحو أثرها زي ما الماء بيطفئ النار، والمقصود هنا برظه بصدقة التطوع مش الزكاة.\n◇وَصَلَاةُ الرَّجُلِ فِي جَوْفِ اللَّيْلِ هي كمان بتكفر السيئات وتطفئ الخطيئة\nوقرأ رسول الله ﷺ على معاذ قول ربنا:\n\" تَتَجَافَى جُنُوبُهُمْ عَنِ الْمَضَاجِعِ يَدْعُونَ رَبَّهُمْ خَوْفًا وَطَمَعًا وَمِمَّا رَزَقْنَاهُمْ يُنْفِقُونَ ۩ فَلَا تَعْلَمُ نَفْسٌ مَا أُخْفِيَ لَهُمْ مِنْ قُرَّةِ أَعْيُنٍ جَزَاءً بِمَا كَانُوا يَعْمَلُونَ\"\nيعني كان جزاءهم من نفس جنس عملهم، هم أخفوا الصلاة في الليل لله؛ كذلك ربنا أخفى لهم الجزاء العظيم في الدنيا وهيعرفوه يوم القيامة\nوأكمل رسول الله ﷺ كلامه قال لمعاذ:\n\"أَلَا أُخْبِرُكَ بِرَأْسِ الْأَمْرِ وَعَمُودِهِ وَذُرْوَةِ سَنَامِهِ؟\"\nيعني تحب أقولك إيه رأس الدين وأصله والعمود إللي بيقوم عليه وأعلى نقطة فيه،\nفقال له معاذ: بَلَى يَا رَسُولَ اللَّه!\nقال رسول الله ﷺ:\n\"رَأْسُ الْأَمْرِ الْإِسْلَامُ، وَعَمُودُهُ الصَّلَاةُ، وَذُرْوَةُ سَنَامِهِ الْجِهَادُ\"\nمفيش حد يقدر يعيش بدون رأس، عشان كده رسول الله ﷺ بيقول لمعاذ إن الدين إللي الإنسان ميقدرش يعيش من غيره هو الإسلام،\nوالعمود إللي يقيم الإسلام ده هو الصلاة، يعني بالمحافظة على الصلاة يقوى دين الإنسان ويشتد زي كده الخيمة إللي لا يُقيمها ويخليها مشدودة وثابتة غير العمود بتاعها\nأما أعلى شيء في الإسلام وأرفعه بعد الفرائض هو الجهاد في سبيل الله.\nوبعدها رسول الله ﷺ قال لمعاذ:\nأَلَا أُخْبِرُكَ بِمِلَاكِ ذَلِكَ كُلِّهِ؟\nيعني تحب أقولك إللي يكمل الأعمال دي كلها ويتمه، قال معاذ بن جبل رضي الله عنه:\n بَلَى يَا رَسُولَ اللَّهِ!\nفَأَخَذَ بِلِسَانِهِ، قَالَ: كُفَّ عَلَيْكَ هَذَا\nيعني رسول الله ﷺ مسك لسانه شخصيا وقال لمعاذ اترُكِ الكلامَ المحرَّمَ كالكلام الذي فيه شِركٌ باللهِ تعالى، والكَذِبِ، وشَهادةِ الزُّورِ، والقولِ على اللهِ بغيرِ عِلمٍ، والخوضِ في أعراضِ النَّاسِ، وغيرِ ذلك مِن الموبِقاتِ كالغِيبةِ والنميمةِ والفُحشِ مِن القولِ وغيره،\nواتْرُكِ الكلامَ فيما لا يُفيدُ وفيما لا مَعنى له؛ فإذا تَكلَّمتَ فلا تَتكلَّمُ إلَّا بخير؛ كالأمْرِ بالصَّدقةِ والمعروفِ أو الإصلاحِ بينَ الناسِ ونحو ذلك؛ فإنْ لم يكُنْ في الكلامِ خيرٌ ففي الصَّمتِ السَّلامةِ،\nوقد قال رسول الله ﷺ في حديث تاني:\n\"مَن كان يُؤمِنُ باللهِ واليومِ الآخِرِ فليقلْ خيرًا أو ليَصْمُتْ\"\nفمعاذ رضي الله عنه قال:\nيَا نَبِيَّ اللَّهِ، وَإِنَّا لَمُؤَاخَذُونَ بِمَا نَتَكَلَّمُ بِهِ؟\nيعني هو احنا هنتحاسب على الكلام إللي بنقوله يارسول الله\nفَقَالَ رسول الله ﷺ:\n\"ثَكِلَتْكَ أُمُّكَ، وَهَلْ يَكُبُّ النَّاسَ فِي النَّارِ عَلَى وُجُوهِهِمْ، أَوْ قَالَ عَلَى مَنَاخِرِهِمْ إِلَّا حَصَائِدُ أَلْسِنَتِهِمْ\"\nثكلتك أمك معناها فقدتك، وهنا رسول الله ﷺ مش بيدعي على معاذ، هي كلمة مِن كلامِ العرَبِ، ورسول الله ﷺ استعملها هنا عشان يُنبه معاذ إن دي حاجة كان لازم يعرفها وينتبه لها لوحده، وهي إن مفيش حاجة هتوقع الناس وتصرعهم على وجوههم إلَّا بسبَبِ ما يَحصُدونه يومَ القيامةِ مِن كَثرةِ الكلامِ في الدُّنيا في غيرِ طاعةِ اللهِ عزَّ وجلّ\n☆وهنا في معلومة يا جماعة:\nلما رسول الله ﷺ بيدعو على أحد من أصحابه زي ما قال لمعاذ بن جبل كده: ثكلتك أمك يا معاذ،\nفهو بمثابة المَنْقَبَة والأجر للصحابي ده، والدليل على كده إن رسول الله ﷺ قال:\n \"إنِّي اشْتَرَطْتُ عَلَى رَبِّي فَقُلْتُ :\n إِنَّمَا أَنَا بَشَرٌ أَرْضَى كَمَا يَرْضَى الْبَشَرُ ، وَأَغْضَبُ كَمَا يَغْضَبُ الْبَشَرُ،\nفَأَيُّمَا أَحَدٍ دَعَوْتُ عَلَيْهِ مِنْ أُمَّتِي بِدَعْوَةٍ لَيْسَ لَهَا بِأَهْلٍ أَنْ يَجْعَلَهَا لَهُ طَهُورًا وَزَكَاةً وَقُرْبَةً يُقَرِّبُهُ بِهَا مِنْهُ يَوْمَ الْقِيَامَةِ\"\nيعني رسول الله ﷺ بيقول إنه زي البشر ممكن ينفعل وممكن يدعو على أحد من باب الجُمل المشهورة عند العرب زي ثكلتك أمك،\nفهو سأل ربنا إنه لو قال الكلام ده يجعل كلامه دعاء بالرحمة وبالقرب من الله يوم القيامة،\nيعني باختصار هو سأل ربنا إن دعاؤه عليهم يتحول لدعاء لهم بالرحمة ورفعة المنزلة والمكانة يوم القيامة \nوده كان أول حدث يحصل في رحلة الرجوع للمدينة،\nإن شاء الله المرة الجاية هنكمل باقي أحداث رحلة الرجوع"}, {"n": 224, "l": "الجزء 198 | احداث السنه التاسعه من الهجرة | رجوع الرسول للمدينه بعد تبوك", "u": "https://www.facebook.com/groups/710210019782034/permalink/836552637147771/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#رجوع_رسول_للمدينة_بعد_تبوك\nاتكلمنا المرة إللي فاتت عن تحرّك الجيش من أرض تبوك ورجوعه للمدينة وشوفنا الحوار إللي دار بين معاذ بن جبل رضي الله عنه وبين رسول الله ﷺ، \nوشوفنا إزاي رسول الله ﷺ نبّه معاذ رضي الله عنه من خطورة اللسان وإن بسبب اللسان الإنسان ممكن يخرج من الإسلام للكفر بسبب كلمة قالها وهو مش واخد باله أو وهو بيهزر زي الموقف إللي حصل مع بعض المنافقين وضعيفي الإيمان\nإيه إللي حصل\nكان في كم واحد ماشيين مع بعض في طريق الرجوع للمدينة، \nوكانوا خليط من المنافقين وبعض ضعيفي الإيمان وكان  معاهم واحد من الصحابة هو عوف بن مالك رضي الله عنه صاحب حديث اعدُد ستا بين يدي الساعة،\nفواحد من المنافقين قال:\nما رأيت مثل قرّائِنا هؤلاء أرغبُ بطونًا ولا أكذب ألسُنًا ولا أجبنُ عند اللقاء\nيعني بيقول عن رسول الله ﷺ والصحابة إنهم كذابين وجبناء ومش بيهمهم غير إشباع بطونهم وإنه مشفش حد في كذبهم وجبنهم،\nفضعيفي الإيمان ضحكوا على كلامه أما الصحابي عوف بن مالك فقال له:\nكذبت! ولكنك منافق! لأخبرنّ رسول الله ﷺ \nوتوجه عوف بن مالك لرسول الله ﷺ عشان يقوله إللي حصل لقى إن الوحي نزل وأخبر رسول الله ﷺ بالكلام إللي قالوه،\nفجاء المنافق لرسول الله ﷺ وقعد يعتذر له ويقول يا رسول كنت بهزر وده كان حديث رَكْب، يعني كنا بنتسلى بالكلام،\nفقال له رسول الله ﷺ:\n\"أَبِاللَّهِ وَآيَاتِهِ وَرَسُولِهِ كُنْتُمْ تَسْتَهْزِئُونَ\"\nوطبعا نتيجة الاستهزاء برسول الله ﷺ وبآيات الله هي الكفر زي ما ربنا قال:\n\"لَا تَعْتَذِرُوا قَدْ كَفَرْتُمْ بَعْدَ إِيمَانِكُمْ\"\nوإللي جاء واعتذر لرسول الله ﷺ ده مكنش ندمان ومعترف بغلطه ده بيظهر الاعتذار والنفاق في قلبه عادي،\nفدول ربنا لم يعفوا عنهم، لكنه عَفى عن إللي كفروا من ضعاف الإيمان إللي ضحكوا على كلام المنافق، \nوهم كفروا لأنهم لما ضحكوا كانوا راضيين عن الكلام إللي المنافق ده قالوا ولم يُنكروا عليه وبالتالي دخلوا في دائرة الكفر،\nفلما تابوا وعرفوا خطأهم ربنا تاب عليهم وعفى عنهم،\nربنا قال:\n\"إِن نَّعْفُ عَن طَائِفَةٍ مِّنكُمْ نُعَذِّبْ طَائِفَةً بِأَنَّهُمْ كَانُوا مُجْرِمِينَ\"\n☆ملحوظة: \nتفسير الآيات دي فيها أقوال كتير للعلماء وتفصيل كتير، فأنا قلت لكم المعنى العام فقط، إللي عايز بقى يتوسع أكتر يراجع كتاب الصارم المسلول على شاتم الرسول وكتاب مجموع الفتاوى لشيخ الإسلام ابن تيمية، \nوهتلاقوا في التعليقات\n روابط لموقع أهل الحديث والإسلام سؤال وجواب فيها التفصيل\nاستمر الجيش في طريق الرجوع للمدينة، وكانوا بيمشوا بالنهار ويريّحوا بالليل، \nفي ليلة من الليالي قام عبد الله بن مسعود من النوم فشاف شعلة من نار في ناحية المعسكر،\nفخرج يشوف الموضوع فاتبع الشعلة فلقى رسول الله ﷺ  وأبو بكر وعمر،\nوكان في صوت حَفر، فاستغرب في إيه، فلقى إن واحد من الصحابة اسمه عبد الله ذو البجادين قد مات،\nفكانوا هم الثلاثة إللي دفنوا عبد الله ذو البِجَادَيْن،\nطبعا مكانة عظيمة تخيلوا رسول الله ﷺ وأبو بكر وعمر بيدفنوا واحد من الصحابة،\nورسول الله ﷺ بعد ما دفنه قال:\nاللهم إني أمسيتُ عنه راضياً فارض عنه\nوعبد الله ذو البِجَادَيْن كان تأخر إسلامه ولما كان عايز يسلم منعه قومه عن الإسلام وضيّقوا عليه لدرجة إنهم أخذوا منه كل ملابسه وتركوا له بِجَاد، وهو الكِساء الغليظ، يعني زي لحاف من الصوف الخشن كده،\nفشقّه اثنين ولبسهم وبعدين راح لرسول الله ﷺ فسُمّي ذو البِجَادَيْن، \nومات في طريق الرجوع للمدينة من غزوة تبوك رضي الله عنه.\nكمل الجيش في طريق العودة، وصل رسول الله ﷺ لمكان اسمه العقبة، والعقبة دي عبارة عن هضبة مرتفعة زي جبل صغير وطرفها فيه حافة منحدرة شديدة،\nفرسول الله ﷺ توجه للعَقَبة دي وأمر منادي ينادي في الناس رسول الله ﷺ هيتجه للعقبة فمحدش يروح وراه، وأخد معاه حُذيفة بن اليَمان وعمار بن ياسر،\nفتقدم رسول الله ﷺ الجيش وطلع العقبة ومعاه حذيفة وعمار، \nوقف رسول الله ﷺ على طرف العقبة أو الهضبة دي ينظر للجيش وهو معدّي، يعني بيستعرض الجيش وبيشوف انضباطه ويشوف لو كان في أي مشكلة في الجيش،\nفي نفس الوقت مجموعة من المنافقين من بني تميم من إللي أظهروا الإسلام ولكنهم كانوا كفار شافوا الموقف ولقوا إن دي فرصة متتعوضش لاغتيال رسول الله ﷺ،\nلأنه في العادة بيبقى حواليه ناس لكن المرة دي مش معاه غير رجلين اتنين بس،\nفقرروا إنهم يخفوا وجوههم ويطلعوا على الهضبة إللي رسول الله ﷺ واقف عليها ويزاحموه ويوقّعوه من فوق الهضبة ويقتلوه\nوفعلا اجتمع أربعة عشر رجلا من بني تميم كلهم مُلثّمِين، يعني مغطيين وجوههم وانطلقوا ناحية العقبة،\nرسول الله ﷺ شافهم وهمّ جايين فغضب غضب شديد جدا، لدرجة إن حذيفة بن اليمان رضي الله عنه بيقول إنه شاف الغضب في وجه رسول الله ﷺ، فبينظر للناحية إللي رسول الله ﷺ بينظر لها لقى المجموعة دي جاية،\nففكر إن رسول الله ﷺ غضبان لأنهم خالفوا الأوامر،\nفكان مع حذيفة زي حَربة صغيرة كده توجّه بها ناحيتهم يضرب بها الروّاحل إللي كانوا راكبين عليها عشان يقول لهم يرجعوا وكان معاه عمار رضي الله عنه،\nفخاف المنافقون دول وهربوا، ورجع عمار وحذيفة لرسول الله ﷺ،\nفسأل رسول الله ﷺ عمار إذا كان عرف مين الناس دي،\nفعمار قال له إنه عرف من العلامات إللي موجودة على الرواحل إللي كانوا راكبين عليها همّ من أنهي قبيلة، لكن همّ كانوا مُلثّمين فمعرفش هم مين بالضبط،\nفسأله رسول الله ﷺ:\nهل تدري ما أرادوا ؟\nيعني عارف كانوا عايزين يعملوا إيه، فقال عمار:\nالله ورسوله أعلم\nقال له رسول الله ﷺ:\n\"أرادوا أن يَنفروا برسول الله ﷺ فيَطرَحُوه\"\nيعني كانوا عايزين يزاحموا رسول الله ﷺ ويوقعوه من على الهضبة،\nوعرف رسول الله ﷺ مين المنافقين دول بالاسم عن طريق الوحي وأخبر رسول الله ﷺ حذيفة بأسماءهم\n☆السؤال بقى:\nليه رسول الله ﷺ لم يُقم عليهم الحد لأنهم حاولوا قتله، أو على الأقل كان أمر قبائلهم إنهم يأتوا بهم أو يقتلوهم\n◇أولاً: \nعشان الناس متقولش إن محمد ﷺ يقتل أصحابه.\n◇ثانياً: \nرسول الله ﷺ لا يملك بيّنة أو دليل واضح على أنهم هم الذين حاولوا قتله\nوالبينة المقصودة هنا هي البيّنة الشرعية، مش البينة عن طريق الوحي،\nيعني مفيش دليل محسوس أو قرينة أو شهادة شهود\nيعني حتى عمار وحذيفة إللي كانوا موجودين مشافوش وجوههم فكده حتى مفيش شهود\n☆والموقف ده يعلمنا ألا نقيم حداً أو حكماً على أحد إلا ببينة\nمع إن رسول الله ﷺ كان متأكد تمام التأكد من أسمائهم عن طريق الوحي، لكن سبحان الله هو ده العدل\nومظنش إن مستوى العدل ده موجود في أي دولة من دول العالم\n وعمرنا ما شوفنا زعيم من الزعماء على وجه الأرض يعلم علماً يقينياً إن في مجموعة دبّروا محاولة لاغتياله وبعدين هو يتجاوز عنهم ولا يؤذيهم بأي صورة من صور الإيذاء؛ لأنه لا يملك أدلة قوية تدينهم أو تثبت الجريمة عليهم\nبالعكس بقى، ده مجرد الشك بس ممكن يؤدي لقتل مئات الأبرياء\nالمهم،\nرجع رسول الله ﷺ للمدينة أخيرا بعد الرحلة الشاقة دي، ودي كانت آخر غزوة غزاها رسول الله ﷺ قبل موته\nدخل رسول الله ﷺ للمدينة والمفروض بقى إن الناس في المدينة متوقعين إن المسلمين خاضوا حرب طاحنة مع الرومان، لكن هم لسه مكنوش يعرفوا الأخبار،\nمحدش كان لسه يعرف أي حاجة....ميعرفوش إن الجيش الروماني خاف يخرج لقتال المسلمين،\nولا يعرفوا إن الاختبار الحقيقي مكنش هناك في أرض تبوك ولكنه كان في المدينة قبل الخروج أصلا لتبوك،\nالاختبار كان عبارة عن القدرة على أخذ قرار الجهاد\nإللي يتغلب على نفسه وعلى ظروفه وعلى شهواته وعلى المعوّقات إللي في حياته،\nويتغلب على شياطينه وعلى أقوال المعوّقين والمُثبّطين حوله ويأخذ قرار الجهاد؛ ساعتها هيكون نجح في الاختبار وحتى لو محصلش جهاد بعد كده،\nوإللي يفشل في أخذ القرار فهو ده إللي اتهزم داخلياً لأنه مقدرش ياخد القرار بسبب خوفه أو أي سبب تاني،\nساعات بتكون النجاة في قرار بناخده في لحظة معينة،\nفلو أخدنا القرار ده ربنا بيكفينا ما كنا نتوقع من مصائب وأذى وألم\nوحياة كل واحد فينا مليانة بالمواقف إللي شَبه كده لو تدبرنا حياتنا كويس\nبعد ما وصل رسول الله ﷺ  للمدينة، وعرف الناس الآثار الحميدة والنتائج العظيمة لغزوة تبوك، بدأ يأتي لرسول الله ﷺ كل الناس إللي تخلفت عن الجهاد بغير عذر عشان يعتذروا منه، \nقبل الخروج لتبوك جاء بعض المنافقين لرسول الله ﷺ يستأذنوه إنهم ميخرجوش للقتال،\nفرسول الله ﷺ كان أذن لهم، حتى ربنا عاتب رسول الله ﷺ إنه المفروض مكنش يأذن لهم عشان يتبين له الصادقين منهم من الكاذبين،\nلأنهم كانوا قالوا إننا هنستأذن رسول الله ﷺ ولو أذن لنا هنقعد ولو لم يأذن لنا برده هنقعد،\nفربنا كان يريد إن رسول الله ﷺ ميأذنش لهم عشان يتفضح أمرهم،\nربنا قال:\n\" عَفَا اللَّهُ عَنْكَ لِمَ أَذِنْتَ لَهُمْ حَتَّى يَتَبَيَّنَ لَكَ الَّذِينَ صَدَقُوا وَتَعْلَمَ الْكَاذِبِينَ\"\nفي بقى ناس تخلفوا من الأعراب والمنافقين من غير حتى ما يستأذنوا من رسول الله ﷺ ، فدول بقى إللي جاءوا لرسول الله ﷺ عشان يعتذروا منه لعدم خروجهم معاه ويطلبوا منه إنه يستغفر لهم، \n\" يَعْتَذِرُونَ إِلَيْكُمْ إِذَا رَجَعْتُمْ إِلَيْهِمْ قُلْ لَا تَعْتَذِرُوا لَنْ نُؤْمِنَ لَكُمْ قَدْ نَبَّأَنَا اللَّهُ مِنْ أَخْبَارِكُمْ\"\nوقعدوا بقى يحلفوا لرسول الله ﷺ إن كان عندهم عذر وإنهم مش هيتخلفوا عن أي قتال هيحصل تاني،\nورسول الله ﷺ قَبِل اعتذارهم وهو عارف إنهم كاذبين، هو فقد فيهم الأمل أصلا فأجرى الأمور على ظاهرها\nكان في بقى ثلاثة من الصحابة تخلفوا عن رسول الله ﷺ في الغزوة دي، وكان منهم الصحابي كعب بن مالك رضي الله عنه،\nلما جاء رسول الله ﷺ للمدينة ودخل المسجد جاءه كعب بن مالك، فلما شافه رسول الله ﷺ تبسم له تبسُّم المُغضب،\nيعني ابتسم ابتسامة فيها غضب\nيا ترى بقى رسول الله ﷺ قال له إيه؟\nوإيه هي قصة كعب بن مالك من البداية؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 225, "l": "الجزء 199 | احداث السنه التاسعه من الهجرة | كعب بن مالك الجزء الأول", "u": "https://www.facebook.com/groups/710210019782034/permalink/836552763814425/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وتسعة_وتسعون\n#أحداث_السنة_التاسعة_من_الهجرة\n#كعب_بن_مالك_الجزء_الأول\nوقفنا المرة إللي فاتت عند كعب بن مالك رضي الله عنه لما راح لرسول الله ﷺ في المسجد بعد ما كان رسول الله ﷺ رجع خلاص من تبوك،\n ودخل كعب المسجد وسلّم،\nفلما رسول الله ﷺ شافه تبسم له تبسُّم المُغضب وقال له:\nتَعَالَ\nفتوجه كعب لرسول الله ﷺ لحد ما قعد قصاده، فقال له رسول الله ﷺ:\nمَا خَلَّفَكَ؟ أَلَمْ تَكُنْ قَدِ ابْتَعْتَ ظَهْرَكَ؟\nيعني إيه إللي خلاك متخرجش للغزوة، مش انت كنت اشتريت البعير إللي هتركب عليه وعندك الزاد إللي يخليك تشارك في الغزوة؟\nيا ترى بقى كعب رد على رسول الله ﷺ قاله إيه\nخلونا نرجع بالزمن كده شوية ونشوف قصة كعب بن مالك رضي الله عنه من البداية كانت إيه\n هنرجع للفترة إللي رسول الله ﷺ كان بيجهز فيها الجيش للخروج إلى تبوك،\nكعب بن مالك بيحكي عن نفسه وعن الأحداث إللي حصلت معاه وبيقول إنه عمره ما تخلّف عن غزوة غزاها رسول الله ﷺ قبل تبوك ما عدا غزوة بدر؛ \nلأن مكنش حد يعرف أصلا إن كان هيبقى في قتال وهم خرجوا عشان يعترضوا قافلة لقريش زي ما قلنا قبل كده،\nورسول الله ﷺ لم يعاتب أحد إنه مخرجش لغزوة بدر،\nفغزوة بدر هي الغزوة الوحيدة إللي محضرهاش كعب رضي الله عنه قبل غزوة تبوك،\n☆وهنا في ملاحظة ممكن مناخدش بالنا منها وهي إن كعب بن مالك لم يسمح للظروف إنها تأثر عليه\nيعني واحد خرج مع رسول الله ﷺ في كل الغزوات، مش معقول يعني إن ظروفه كانت مناسبة إنه يخرج في الغزوات دي كلها\nيعني تخيلوا إنه خرج في حوالي تسعة عشرة غزوة،\nباعتبار القول إن عدد غزوات رسول الله ﷺ واحد وعشرين غزوة،\nفهو محضرش غزوة بدر ومحضرش غزوة تبوك، يبقى هو خرج مع رسول الله ﷺ في تسعة عشر غزوة،\nفإزاي بقى مكنش عنده أي ظرف خلال التسعة عشر غزوة دول، واحنا عارفين إن الظروف متغيرة\nفده يدل على إن كعب بن مالك رضي الله عنه مسمحش لأي ظرف يحصل له في حياته إنه يأثر عليه ويمنعه من الخروج للجهاد مع رسول الله ﷺ\nولو جينا شوفنا الواقع بتاعتنا هتلاحظوا إن مواعيد الصلاة في أوقات مختلفة أو خلونا نقول في ظروف مختلفة، \nيعني سواء الواحد كان نايم فيقوم من نومه عشان يصلي الفجر،\nأو كان في شغله فيسيب شغله ويسيب دنيته عشان يروح يصلي الظهر، أو كان مريّح فيسيب راحته ويقوم يصلي العصر وهكذا،\nفده ابتلاء واختبار من ربنا عشان يشوف إذا كنا هنسيب الظروف هي إللي تتحكم فينا أو احنا إللي نخلي الصلاة فوق كل الظروف\nطيب إزاي واحد كان حريص الحرص ده كله على حضور غزوات رسول الله ﷺ ميحضرش الغزوة المهمة دي إللي رسول الله ﷺ أَلزم فيها الناس بالخروج مادام يقدر إنه يخرج\nكعب بن مالك بيقول:\n\"وَكَانَ مِنْ خَبَري حينَ تَخَلَّفْتُ عَنْ رسولِ اللهِ ﷺ فِي غَزْوَةِ تَبُوكَ أَنِّي لَمْ أَكُنْ قَطُّ أَقْوَى وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْهُ فِي تِلْكَ الْغَزْوَةِ،\nوَاللهِ مَا جَمَعْتُ قَبْلَهَا رَاحِلَتَيْنِ قَطُّ حَتَّى جَمَعْتُهُمَا فِي تِلْكَ الْغَزْوَةِ\"\nيعني هو بادئ كلامه بيقول إنه ملوش عذر، بالعكس بقى دي كانت أكتر غزوة معاه فيها فلوس، \n وكمان كان عنده راحلتين مش واحدة، يعني عنده بعيرين يقدر يوصل بيهم لتبوك،\nوكان قوي من الناحية البدنية، يعني مكنش عنده أي تعب أو إجهاد،\nكمل كعب بن مالك الكلام وقال إن رسول الله ﷺ في غزوة تبوك كان أعلن عن مكان الغزوة بكل وضوح عشان الناس تستعد زي ما قلنا قبل كده،\nواجتمع لرسول الله ﷺ عدد كبير من المسلمين وَلَا يَجْمَعُهُمْ كِتَابٌ حَافِظٌ،\nيعني مفيش غياب...مفيش دفتر مكتوب فيه أسماء المسلمين إللي حضروا وهيخرجوا للغزو ومين إللي تخلف عن الخروج،\nقال كعب:\n\"فَقَلَّ رَجُلٌ يُريدُ أَنْ يَتَغَيَّبَ إِلَّا ظَنَّ أَنَّ ذَلِكَ سَيَخْفَى بِهِ مَا لَمْ يَنْزِلْ فِيهِ وَحْيٌ مِنَ اللهِ\"\nيعني كل واحد بيغيب بيبقى عارف إنها غالبا هتعدي، لأن المسلمين كتير يعني كأنه بيقول هي جت عليّ أنا ما في غيري كتير هيطلع، وفي وسط الزحمة دي رسول الله ﷺ مش هياخد باله أصلا،\nإلا بقى لو نزل قرآن يذكر الشخص ده بعينه فدي هتبقى قضية تانية،\n\"وَغَزَا رَسُولُ اللهِ ﷺ تِلْكَ الْغَزْوَةَ حِينَ طَابَتِ الثِّمَارُ وَالظِّلَالُ، فَأَنَا إِلَيْهَا أَصْعَرُ\"\nيعني كعب بيقول إن وقت خروج الغزوة كان وقت نضوج الثمار و نفسه كانت مشتاقة جدا إنه يجني الثمار ومش عايز يخرج دلوقتي،\nفالمسلمين بدأوا يتجهزوا للخروج، فخرج هو كمان عشان يتجهز معاهم لكن نفسه مش عايزة تخرج دلوقتي،\nفقعد بقى يلف ويشوف هو محتاج إيه، وفي الآخر مجبش حاجة ولم يتجهز،\nزي كده لما الواحد فينا بيبقى مضطر إنه يشتري حاجة بس مش عايز، فيقعد يلف في السوق كده مش عاجبه حاجة ويتحجج إن ده وحش وإن ده مش على مزاجه وهكذا،\nفبعد ما رجع كعب من غير ما يشتري الحاجات إللي محتاجها للغزو كان بيقول في نفسه:\n\"أَنَا قَادِرٌ عَلَى ذَلِكَ إِذَا أَرَدْتُ\"\nيعني أنا لسه عندي وقت وعندي الفلوس هقدر انزل اشتري إللي أنا عايزه وقت ما أنا عايز.\n☆ودي نقطة خطيرة جدا يا جماعة\nنقطة التسويف وإن الواحد يفضل يأجل...يأجل لآخر لحظة، في الغالب إللي بيقعد يأجل كده بيضيع عليه خير كتير،\nواحد مثلا عايز يصلي الضحى وهو مشغول في حاجة،\nفيقول ده لسه بدري، لسه عندي وقت ولسه أذان الظهر فاضل عليه ساعتين ثلاثة،\nفالشيطان ينسيه ويشغله أكثر لحد ما يتفاجأ إن الظهر أذن وضاعت عليه صلاة الضحى\nزي ما حصل مع كعب بن مالك كده، قعد يسوّف ويأجل ومأخدش نفسه بالعزيمة وألزم نفسه بإنه يتجهز من بدري، وهو نفسه قال:\n\"فَلَمْ يَزَلْ يَتَمَادَى بِيَ حَتَّى اسْتَمَرَّ بِالنَّاسِ الْجِدُّ\"\nيعني الناس أخدت الموضوع جد وفجأة عزموا وانطلقوا مع رسول الله ﷺ للغزو وهو لسه مجهزش أي شيء،\nوخرج تاني عشان يشتري الحاجات إللي محتاجها ورجع من غير ما يجهز أي شيء وهو في باله إنه هيقدر يحصلهم في أي وقت،\nسبحان الله لو الشيطان كان قاله من البداية منتش خارج للغزوة، كان هيقوله لأ هخرج للغزوة\nلكن هي خطوات الشيطان بيمشي بيها مع الإنسان لحد ما يوقعوا في الخطأ أو يضيع عليه أجر عظيم\nوالوضع استمر معاه كده، ييجي يقول هطلع، نفسه والشيطان يقولوا لسه بدري متقلقش هتقدر تلحقهم،\nلحد ما رسول الله ﷺ وجيش المسلمين خرجوا بقى في اتجاه تبوك وبقوا قريبين منها، والموضوع خرج من إيده خلاص،\nوقال كلمة مهمة :\n\"فَهَمَمْتُ أَنْ أرْتَحِلَ فَأُدْرِكَهُمْ، فَيَا لَيْتَني فَعَلْتُ، ثُمَّ لم يُقَدَّرْ ذَلِكَ لِي\"\nيعني بالرغم من إنهم خلاص بعدوا وبقى صعب يلحقهم وكان في اللحظة دي فاقد فيها الأمل إنه يلحقهم قال خليني ألحقهم وخلاص وزي ما تيجي تيجي حتى لو هموت في الصحراء؛\nلكن نفسه قالت له خلاص الموضوع مبقاش له لازمة، فهو بيتندم إنه مخرجش يلحق بيهم حتى لو كان شايف إن الموضوع مكنش له لازمة،\n وهنا يحضرنا موقف أبو خيثمة رضي الله عنه، فاكرينه،\nكان في الأول تكاسل عن الخروج وبعدين رفض إنه يدخل على زوجتيه وأمرهم إنهم يجهزوا له راحلته عشان يلحق برسول الله ﷺ،\nوفعلا لحق برسول الله ﷺ ورسول الله ﷺ كان قاله:\n\"أَوْلَى لَكَ يا أبا خَيْثَمةَ\"\nفعندنا دلوقتي منموذجين، نموذج تكاسل في البداية ومع ذلك خرج بعدين، ونموذج تاني تكاسل في البداية ونفسه والشيطان غلبوه ولم يخرج للغزو،\nفالموضوع يا جماعة مكنش موضوع توافر أسباب أو لأ، كل أسباب الخروج كانت متوفرة عند كعب بن مالك من مال وراحلة وقوة في البدن ومع ذلك مخرجش\nالواحد فينا ممكن يكون عايز يعمل حاجة معينة، زي مثلا إنه يحفظ القرآن أو يطلب علم شرعي،\nفيقول يا سلام لو ألاقي دار لتحفيظ قرآن جنب البيت أو يبقى في مكان لتعليم العلم الشرعي مش هتأخر أبدا وهتعلم على طول،\nفربنا ييسر وتتوفر الأسباب لحفظ القرآن ودراسة العلم الشرعي ويتوفر الوقت وكل حاجة والإنسان لا يحفظ ولا يتعلم، ليه؟\nلأن الموضوع بيبقى توفيق من عند ربنا وعزيمة القلب، الإنسان لما بيبقى عايز يقرب من ربنا بيقرب بغض النظر عن الأسباب، \nلكن لما يعتمد على الأسباب ويربط نجاح عمله بتوفر الأسباب ربنا فعلا بيوفر له الأسباب عشان يخليه يشوف إن التقصير من عند نفسه والعيب فيه وفي التسويف والتأجيل بتاعه مش في توافر الأسباب من عدمها\nفكعب رضي الله عنه بيتندم ويقول يا ريتني كنت خرجت وخلاص حتى لو كنت شايف إن الوقت اتأخر ومفيش فايدة في الخروج،\nفكان ساعتها يوصل متأخر زي أبو خيثمة بدل من إنه ميوصلش خالص ويبقى قاعد في المدينة مع المنافقين إللي تخلفوا عن رسول الله ﷺ ومعروف إنهم كانوا منافقين،\nقال كعب:\n\"فَطَفِقْتُ إِذَا خَرَجْتُ فِي النَّاسِ بَعْدَ خُرُوجِ رَسُولِ اللهِ ﷺ  يَحْزُنُنِي أَنِّي لَا أَرَى لِيَ أُسْوَةً، إِلَّا رَجُلًا مَغْمُوصًا عَلَيْهِ في النِّفَاقِ، أَوْ رَجُلًا مِمَّنْ عَذَرَ اللهُ تَعَالَى مِنَ الضُّعَفَاءِ\"\nيعني كعب بيقول إنه كان لما يخرج بين الناس بعد ما رسول الله ﷺ خرج للغزو كان بيبقى حزين إن هو لوحده في الأزمة ومحدش من أصحاب الفضل موجود معاه،\nومفيش في المدينة إلا نوعين من الرجال:\n◇النوع الأول :\nالمستضعفين من المسلمين إللي ربنا عذرهم لأنهم إما ضعفاء أو معندهمش راحلة يسافروا عليها.\n◇والنوع الثاني:\nالمنافقين الغرقانين في النفاق ومعروف إن دول منافقين.\nفكان حزين رضي الله عنه إنه مش لاقي حد شبهه من إللي كانوا بيخرجوا معاه في الغزوات،\nوكأن لسان حاله بيقول أنا إيه إللي مقعدني مع الناس دي، إما واحد معذور أو منافق، طب انا وضعي إيه، فكان إحساس صعب،\nفي الوقت ده بقى بعد ما رسول الله ﷺ وصل لتبوك وكان قاعد مع الصحابة سأل عن كعب بن مالك زي ما قلنا قبل كده، وقال:\nمَا فَعَلَ كَعْبُ بْنُ مَالِكٍ؟\nفَقَالَ رَجُلٌ مِنْ بَنِي سَلِمَةَ: يا رَسُولَ اللهِ، حَبَسَهُ بُرْدَاهُ وَالنَّظَرُ فِي عِطْفَيْهِ، \nفَقَالَ لَهُ مُعَاذُ بْنُ جَبَلٍ :بِئْسَ مَا قُلْتَ! وَاللهِ يَا رَسُولَ اللهِ مَا عَلِمْنَا عَلَيْهِ إِلَّا خَيْرًا، فَسَكَتَ رَسُولُ اللهِ ﷺ \nوسكوت رسول الله ﷺ هنا لأن خلاص معاذ دافع عن كعب ورد غيبته، وأنكر منكر الغيبة،\nوكمان رسول الله ﷺ ميقدرش يتكلم أصلا لا بالنفي ولا بالإثبات لأن هو معندوش دليل هل كعب فعلا زي ما الرجل ده بيقول شغلته أمواله،\nولا حصل له ظرف طارئ ومقدرش يخرج، فكان الطبيعي إن رسول الله ﷺ يسكت لأنه لا ينطق عن الهوى ﷺ\n◇في هنا درس مهم أوي بيعلمهولنا كعب رضي الله عنه والصحابة،\nإللي حكي القصة دي هو كعب بن مالك، حكاها لابنه وابنه حكاها للناس من بعده، \nوعلى الرغم من إنه حكى لابنه قصته لكنه لم يذكر اسم الصحابي إللي اتكلم عنه كلام سيء، \nومحدش من الصحابة ذكر اسم الصحابي إللي قال الكلام السيء عن كعب رضي الله عنه،\nمن باب عدم نشر الكره بينهم والوقيعة، ولعل الرجل اعتذر بعدين فمفيش داع إننا نذكره في موضع يُسيء له،\nفي حين إنهم ذكروا موقف معاذ رضي الله عنه وهو بيدافع  عن كعب،\nعشان يعلمونا إن لما واحد من أصحاب الفضل زي كعب بن مالك يقع في ذلة ندافع عنه ونحسن الظن فيه مادام له سابقة فضل وظاهره الخير\nالمهم، \nلما كعب عرف إن رسول الله ﷺ هيرجع للمدينة خلاص؛ شال الهم بقى\nهيعمل إيه مع رسول الله ﷺ وهيقوله إيه وهيعتذر منه إزاي\nفقعد يفكر في كذبة يكذبها عشان يخرج من سخط وغضب رسول الله ﷺ عليه،\nوقعد يستشير أصحاب الرأي من أهله،\nيقول كعب لما سمع كعب الخبر إِنَّ رَسُولَ اللهِ ﷺ قَدْ أَظَلَّ قَادِمًا، زَاحَ عَنِّي الْبَاطِلُ، حَتَّى عَرَفْتُ أَنِّي لَنْ أَنْجُوَ مِنْهُ بِشَيءٍ أَبَدًا، فَأَجْمَعْتُ صِدْقَهُ،\nيعني لما عرف إن رسول الله ﷺ خلاص جاي كل الكذب إللي كان بيجهز له اختفى، وكأن كان في غشاوة على عينه واختفت وعرف إنه مفيش حاجة هتنجيه غير الصدق\nفجاء رسول الله ﷺ ودخل المسجد وصلى ركعتين كعادته وقعد يكلم الناس وجاء الْمُخَلَّفُونَ يَعْتَذِرُونَ إِلَيْهِ، وَيَحْلِفُونَ لَهُ، وَكَانُوا بِضْعًا وَثَمَانِينَ رَجُلًا، \nفَقَبِلَ مِنْهُمْ عَلَانِيَتَهُمْ، وَبَايَعَهُمْ، واسْتَغْفَرَ لَهُمْ، وَوَكَلَ سَرَائِرَهُمْ إِلَى اللهِ تَعَالَى،\nواحنا شرحنا الكلام ده كله قبل كده، وقلنا إن إللي تخلفوا عن رسول الله ﷺ من المنافقين جاءوا ليعتذروا ويحلفوا لرسول الله ﷺ إنهم كانوا معذورين وطلبوا من رسول الله ﷺ إنه يستغفر لهم،\nوجاء كعب بقى لرسول الله ﷺ وسلم عليه وتبسم له رسول الله ﷺ تبسّم المُغضَب وقال له:\n\" مَا خَلَّفَكَ؟ أَلَمْ تَكُنْ قَدِ ابْتَعْتَ ظَهْرَكَ؟\"\nفرد عليه كعب بن مالك وقال له:\nيَا رَسُولَ اللهِ،\nإِنِّي وَاللهِ لَوْ جَلَسْتُ عِنْدَ غَيْرِكَ مِنْ أَهْلِ الدُّنْيَا لَرَأيتُ أَنِّي سَأَخْرُجُ مِنْ سَخَطِهِ بِعُذْرٍ؛ لَقَدْ أُعْطِيتُ جَدَلًا، \nولَكِنِّي وَاللهِ لَقَدْ عَلِمْتُ لَئِنْ حَدَّثْتُكَ الْيَوْمَ حَدِيثَ كَذِبٍ تَرْضَى بِهِ عَنِّي لَيُوشِكَنَّ اللهُ أَنْ يُسْخِطَكَ عَلَيَّ،\nوَإِنْ حَدَّثْتُكَ حَدِيثَ صِدْقٍ تَجِدُ عَلَيَّ فِيهِ، إِنِّي لَأَرْجُو فِيهِ عُقْبَى اللهِ - عَزَّ وَجَلَّ -\nوَاللهِ مَا كَانَ لِيَ مِنْ عُذْرٍ، \nوَاللهِ مَا كُنْتُ قَطُّ أَقْوَى وَلَا أَيْسَرَ مِنِّي حِينَ تَخَلَّفْتُ عَنْكَ\nيعني كعب بن مالك بيقول لرسول الله ﷺ إنه لو قعد قصاد أي حد من أهل الدنيا هيقدر يقنعه ويغلبه بكلامه ويسترضيه لأنه بيقدر يجادل ويقنع إللي قصاده،\nولكن هو عارف إنه لو كذب عليه وقاله كلام يسترضيه به ربنا هيغضب عليه،\nولو هو قال الحقيقة رسول الله ﷺ هيزعل ويغضب منه لكن يرجو إن ربنا يدخر له أجر الموقف ده ويعامله بلطفه،\nفحلف له وقاله إنه مكنش له عذر بالعكس ده أكتر وقت عنده مال وقوة في البدن.\nيا ترى بقى رسول الله ﷺ رد عليه قال له إيه؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 226, "l": "الجزء 200 | احداث السنه التاسعه من الهجرة | كعب بن مالك الجزء الثاني", "u": "https://www.facebook.com/groups/710210019782034/permalink/836552913814410/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين\n#أحداث_السنة_التاسعة_من_الهجرة\n#كعب_بن_مالك_الجزء_الثاني\nاتكلمنا المرة إللي فاتت عن قصة كعب بن مالك رضي الله عنه وشوفنا صدقه واعترافه لرسول الله ﷺ بإنه مكنش عنده أي عذر تخلف بسببه،\nرسول الله ﷺ رد وقال:\n\"أَمَّا هَذَا فَقَدْ صَدَقَ، فَقُمْ حَتَّى يَقْضِيَ اللهُ فِيكَ\"\nيعني بيقول إن كل الناس إللي قبل كده جاءوا يعتذروا ويتحججوا بأسباب؛ كلهم كانوا كاذبين لكن كعب بن مالك هو الوحيد إللي صدق في كلامه،\nفقال له استنى بقى لحد ما ربنا يقضي في أمرك ويقول نعمل إيه معاك،\nفخرج كعب بن مالك من عند رسول الله ﷺ، وخرج وراه رجال من بني سَلَمَة، فقالوا لكعب:\n وَاللهِ مَا عَلِمْنَاكَ أَذْنَبْتَ ذَنْبًا قَبْلَ هذَا\n لَقَدْ عَجَزْتَ فِي أَنْ لَا تَكُونَ اعْتَذَرْتَ إِلَى رَسُولِ اللهِ ﷺ بِمَا اعْتَذَرَ إِلَيْهِ الْمُخَلَّفُونَ\n فَقَدْ كَانَ كَافِيكَ ذَنْبَكَ اسْتِغْفَارُ رَسُولِ اللهِ ﷺ لَكَ\nيعني بيقولوا له احنا منعرفش عنك إنك عملت ذنب كبير قبل كده أو تخلفت عن غزوة، ودي أول مرة، إيه المشكلة يعني، مكنتش عارف تعتذر لرسول الله ﷺ بأي عذر كده زي ما اعتذر باقي الناس إللي تخلفوا،\nكنت اعتذر ورسول الله ﷺ يستغفر لك وخلاص انتهى الموضوع،\nكعب بيقول:\n\"فَوَاللهِ مَا زَالُوا يُؤَنِّبُونَنِي حَتَّى أَرَدْتُّ أَنْ أَرْجِعَ إِلَى رَسُولِ اللهِ ﷺ فَأُكَذِّبَ نَفْسِي\"\nيعني قعدوا يؤنبوه ويلوموه ويقولوا له إيه إللي انت عملته ده، حد يقول: والله ماكان عندي عذر؟! \nإيه يعني لما تتخلف عن غزوة واحدة من غزوات كتير، كفرت يعني...دي حاجة بسيطة، وأهه رسول الله ﷺ استغفر لهم وعايشين حياتهم عادي،\nوفضلوا يقولوا له كلام زي كده،\nومن كتر ضغط كلامهم عليه كعب كان عايز يرجع لرسول الله ﷺ ويكذب نفسه ويقول له لا يا رسول أنا كنت بكذب ده أنا كان عندي عذر وأنا كنت ناسي وافتكرت دلوقتي، \nفبعدين سألهم:\nهَلْ لَقِيَ هذَا مَعِيَ مِنْ أَحَدٍ؟ \nيعني في حد في نفس موقفي ده، تخلف وهو معندوش عذر، وقال لرسول الله ﷺ، قالوا له:\nنَعَمْ، لَقِيَهُ مَعَكَ رَجُلانِ، قَالَا مِثْلَ مَا قُلْتَ، وَقيلَ لَهُمَا مِثْلَ مَا قِيلَ لَكَ\nيعني فعلا في رجلين قالوا نفس كلامك لرسول الله ﷺ  ورسول الله ﷺ رد عليهم بنفس الكلام إللي رد عليك بيه،\nفسألهم مين الرجلين دول فقالوا له:\nمُرَارَةُ بْنُ الرَّبِيعِ الْعَمْرِيُّ، وَهِلَالُ بْنُ أُمَيَّةَ الْوَاقِفِيّ!\nقَالَ كعب: فَذَكَرُوا لِيَ رَجُلَينِ صَالِحَينِ قَدْ شَهِدَا بَدْرًا، فِيهِمَا أُسْوَةٌ، فَمَضَيْتُ حِينَ ذَكَرُوهُما لِي\nيعني همّ ذكروا له رجلين صالحين حضروا غزوة بدر، وكل إللي حضر غزوة بدر له مكانة عظيمة وهم أفضل الناس،\nفهو لما شاف إن في ناس أحسن منه وقالوا نفس الكلام إللي هو قاله لرسول الله ﷺ اطمأنت نفسه وإن إللي عمله ده كان صح، \nوأخد القرار إن مش هيرجع يكذب نفسه زي ما كان بيفكر يعمل، ورجع لبيته واستنى قضاء ربنا زي ما رسول الله ﷺ قال له،\nبدأت بقى العقوبات تنزل على الثلاثة\nأول حاجة حصلت إن رسول الله ﷺ نَهَى الناس إنهم يكلموا الثلاثة دول مِنْ بَيْنِ مَنْ تَخَلَّفَ عَنْهُ، \nيعني كل إللي تخلفوا عن الغزوة الناس تكلمهم عادي وعايشين حياتهم طبيعي إلا كعب بن مالك مُرَارَةُ بْنُ الرَّبِيعِ وَهِلَالُ بْنُ أُمَيَّةَ،\n☆الواحد ممكن يقول في نفسه يعني هي دي نتيجة الصدق وقول الحق، هو مش الصدق بينجّي صاحبه،\nفين بقى؟\nما كان يكذب وخلاص ويعيش حياته زي الباقيين\nلكن العبرة بالنتيجة وبالنهاية\nهنشوف إن شاء الله نهاية الثلاثة دول كانت إيه\nلما رسول الله ﷺ أمر إن محدش يكلم الثلاثة الذين خُلّفوا؛ كعب بيقول:\n\"فاجْتَنَبَنَا النَّاسُ - أوْ قَالَ: تَغَيَّرُوا لَنَا - حَتَّى تَنَكَّرَتْ لِي فِي نَفْسِي الْأَرْضَ، فَمَا هِيَ بِالْأرْضِ الَّتِي أَعْرِفُ\"\nيعني محدش من الناس بيكلمهم ولا بيتعامل معاهم، لدرجة إنه حس إن الأرض نفسها إللي بيمشي عليها تنكّرت له هي كمان وبقى حاسس إنه في أرض غريبة.\nهلال بن أمية ومرارة بن الربيع كانوا كبار في السن فمستحملوش الضغط ده فقعدوا في بيوتهم يبكوا ويدعوا ربنا،\nلكن كعب رضي الله عنه كان شاب، فكان بيخرج يحضر الصلوات في المسجد مع المسلمين ويمشي في الأسواق بين الناس ومحدش كان بيكلمه نهائي\nوكان يأتي لرسول الله ﷺ في مجلسه وهو قاعد مع الصحابة بعد الصلاة فيسلم عليه،\nفكان كعب بيقول في نفسه: هَلْ حَرَّكَ شَفَتَيْه برَدِّ السَّلَامِ أَمْ لَا؟ \nيعني حتى رسول الله ﷺ مكنش بيكلمه، وكعب ميعرفش إذا كان رسول الله ﷺ رد عليه السلام ولّا لأ،\nوكان يصلي بالقرب من رسول الله ﷺ ويُسارِقه النظر، يعني يبص له من جنب كده يشوف رسول الله ﷺ بيبص عليه ولّا لأ، كعب بيقول:\nفَإِذَا أَقْبَلْتُ عَلَى صَلَاتِي نَظَرَ إِلَيَّ، وَإِذَا الْتَفَتُّ نَحْوَهُ أَعْرَضَ\" عَنِّي\"\nيعني لما كعب بييجي يصلي ويركز في الصلاة رسول الله ﷺ يبص عليه،\nولو كعب التَفت ناحية رسول الله ﷺ يقوم رسول الله ﷺ ملتفت عن كعب وينظر في جهة تانية\nيعني على الرغم من إن رسول الله ﷺ هو إللي قال محدش يكلم كعب والناس تتجنبه وطبعا ده بأمر من ربنا؛ لكنه ﷺ لسه مهتم بيه وصعبان عليه وعايز يطمن عليه فكان بينظر إليه لعله يعرف أحواله،\nيقول كعب:\nحَتَّى إِذَا طَالَ ذَلِكَ عَلَيَّ مِنْ جَفْوَةِ الْمُسْلِمِينَ مَشَيْتُ حَتَّى تَسَوَّرْتُ جِدَارَ حَائِطِ أَبِي قَتَادَةَ وَهُوَ ابْنُ عَمِّي وأَحَبُّ النَّاس إِلَيَّ، فَسَلَّمْتُ عَلَيهِ، \nفَوَاللهِ مَا رَدَّ عَليَّ السَّلَامَ، فَقُلْتُ لَهُ: \nيَا أَبَا قَتَادَةَ، أنْشُدُكَ باللهِ هَلْ تَعْلَمُنِي أُحِبُّ اللهَ وَرَسُولَهُ؟ فَسَكَتَ، فَعُدْتُ فَنَاشَدْتُهُ، فَسَكَتَ، فَعُدْتُ فَنَاشَدْتُهُ، فَقَالَ: اللهُ ورَسُولُهُ أَعْلَمُ، فَفَاضَتْ عَيْنَايَ\nيعني كعب بيقول لما طال جفاء المسلمين عليه راح لأبي قتادة ابن عمه وكان أحب الناس إليه،\nوخدوا بالكم إنه عشان يقابله تسلق سور البستان ودخل من ورا السور؛ لأنه لو كان جاله من الباب كان هيرفض يقابله لأن رسول الله ﷺ قال محدش يكلم الثلاثة،\nفلما شافه كعب سلم عليه، فأبو قتادة مردش عليه السلام،\n☆طيب إزاي ميردش السلام ورد السلام واجب \nلأن كل حقوق كعب بن مالك سقطت بالهجر\nيعني دلوقتي رسول الله ﷺ أمر بالناس بهجر الثلاثة دول، \nويدخل في الهجر هنا عدم رد السلام.\nفكعب استحلف ابن عمه وأقرب الناس له بالله وسأله مش انت عارف إني أحب الله ورسوله، فأبو قتادة مردش عليه.\n◇طيب هو ليه كعب سأل أبا قتادة السؤال ده؟\nيعني هو كعب مش عارف يعني نفسه إذا كان بيحب ربنا ورسوله ولّا لأ\nشوفوا،\nالواحد ساعات في بعض الأزمات بيبقى محتاج حد يطمنه ويثبته ويديله ثقة في نفسه،\nمحتاج حد يقوله متخفش انت كويس وفيك خير والبلاء إللي انت فيه ده هيعدي\nفهو ده إللي كعب كان محتاج يسمعه من أبي قتادة، فلما سأله السؤال ده كان مستني يسمع منه حاجة تطمنه وخصوصا إن أبا قتادة يبقى ابن عمه وأقرب وأحب الناس إليه،\nلكن أبو قتادة سكت ومردش، فكعب كرر عليه السؤال مرة تانية، فهنا أبو قتادة رد بكلام شديد جدا عليه وقال: الله ورسوله أعلم، يعني أنا معرفش إذا كنت فعلا بتحب الله ورسوله ولّا لأ،\nفهنا كعب مستحملش الصدمة وعينه فاضت بالدموع\n☆طيب ما هو أبو قتادة كلمه أهه ورد عليه، يبفى هو كده خالف أمر رسول الله ﷺ \nلأ، أبو قتادة رضي الله عنه لم يخالف أمر رسول الله ﷺ؛ لأن الكلام المنهي عنه هو إن يكون في حوار بين الاتنين،\nيعني واحد يتكلم والتاني يرد عليه ويبقى في بينهم أخذ ورد،\nوأصلا لما أبو قتادة قال الله ورسوله أعلم مكنش يقصد الرد على كعب ولا إنه يتكلم معاه،\nلكنه علَّق محبة كعب بن مالك على علم الله ورسوله،\nعلى الرغم من إن أبو قتادة ممكن يكون عارف من قلبه ومن تصرفات كعب على مدار السنين وهو صاحبه وأقرب الناس له إنه محب لله ورسوله، \nولكن بعد الموقف إللي حصل ده؛ أبو قتادة ميعرفش ربنا هيحكم بإيه في موضوع كعب،\nعشان كده الجملة إللي قالها دي لا تعتبر من الكلام إللي المسلمون نُهوا عنه.\nبعد الكلمة إللي سمعها كعب من أبي قتادة يقول كعب:\n\"وَتَوَلَّيْتُ حَتَّى تَسَوَّرْتُ الْجِدَارَ\"\nيعني قام وتسلق السور وخرج من بستان أبي قتادة،\nوخرج يمشي في سوق المدينة ولكم أن تتخيلوا حالته النفسية كانت عاملة إزاي، وأد إيه كمية الهم والغم والكرب إللي كان فيها\nبعد الموقف ده على طول وهو ماشي في السوق ربنا ابتلاه بابتلاء شديد جدا\nيقول كعب:\n\"فَبَيْنَا أَنَا أَمْشِي فِي سُوقِ الْمَدِينَةِ إِذَا نَبَطِيٌّ مِنْ نَبَطِ أهْلِ الشَّامِ مِمَّنْ قَدِمَ بالطَّعَامِ يَبيعُهُ بِالمَدِينَةِ، يَقُولُ: \nمَنْ يَدُلُّ عَلَى كَعْبِ بْنِ مَالِكٍ؟ \nفَطَفِقَ النَّاسُ يُشِيرُونَ لَهُ إِلَيَّ حَتَّى جَاءنِي فَدَفَعَ إِلَيَّ كِتَابًا مِنْ مَلِكِ غَسَّانَ، وَكُنْتُ كَاتبًا، فَقَرَأْتُهُ، فإِذَا فِيهِ: \nأَمَّا بَعْدُ، فإِنَّهُ قَدْ بَلَغَنا أَنَّ صَاحِبَكَ قَدْ جَفَاكَ، وَلَمْ يَجْعَلْكَ اللهُ بدَارِ هَوانٍ وَلَا مَضْيَعَةٍ، فَالْحَقْ بنَا نُوَاسِكَ\"\nيعني لما كعب كان ماشي في السوق كان في فلاح من فلاحين الشام أو تاجر من التجار إللي جاءوا يبيعوا الطعام في سوق المدينة بيسأل الناس مين يدله على كعب بن مالك،\nفالناس شاوروا له على كعب،\nفجاءه الفلاح وأعطاه كتاب، رسالة يعني وكان كعب بيعرف يقرأ ويكتب، \nففتح الرسالة لقاها من ملك غسّان وكان اسمه جَبَلة بن الأَيْهم، وواضح إنه كان متابع الأخبار والأمور إللي بتحصل في المدينة عشان يستغل أي ظرف لزعزعة الثقة بين المسلمين وبين رسول الله ﷺ،\nالمهم،\nملك غسان بيقول لكعب في الرسالة إنه عرف إن صاحبه يعني رسول الله ﷺ أعرض عنه وبقى يعامله معاملة وحشة، وانت يا كعب مش دي منزلتك ولا انت وش البهدلة والمعاملة السيئة دي،\nواحنا كنا قلنا قبل كده إن كعب كان أمير في قومه.\nفهو بيفكره بمكانته وبيقوله سيبك من الإسلام والناس إللي بيعاملوك معاملة سيئة كده وتعال ادخل في ديننا وهنعاملك أحسن معاملة\nعايزاكم يا جماعة تتخيلوا شدة الابتلاء ده\nواحد بقاله عشرين أو ثلاثين يوم لا أهل ولا أصحاب بيكلموه ولا حتى رسول الله ﷺ، \nيعني مش إنه عايش لوحده، لأ ده بيشوف ناس عارفهم وبيعرضوا عنه، ومش واحد ولا اتنين ده المجتمع كله كده، حتى أقرب الناس إليه أبو قتادة،\nوفي حالة نفسية سيئة جدا وفجأة تجيله رسالة تقوله تعال احنا هنخلصك من الهم إللي انت فيه ده كله،\nأي واحد من ضعيفي الإيمان هيلاقيها فرصة متتعوضش وهيبيع دينه بعرض من الدنيا\nتخيلوا كعب عمل إيه؟\nيقول كعب إنه لما قرأ الرسالة قال:\n\"وَهَذِهِ أَيضًا مِنَ البَلاءِ، فَتَيَمَّمْتُ بِهَا التَّنُّورَ فَسَجَرْتُهَا\"\nيعني هو عرف إن ربنا بيختبره والرسالة دي زيادة في البلاء،\nفراح واخد الرسالة ورماها في الفرن وحرقها عشان يقفل باب الفتنة دي خالص\nماهو كان ممكن يخليها معاه وميروحش برده لملك غسان، لكن كعب عنده فقه وفاهم إنه لو ساب أي باب فتنة مفتوح ممكن يدخله،\nإيه إللي يضمن إن نفسه متضعفش في يوم من الأيام كل ما يشوف الرسالة مع الضغط وشدة الابتلاء وفعلا يروح لملك غسّان\nفهو سد باب الفتنة ده خالص وبِعد عنه\n☆الواحد فعلا مش عارف يتعجب من الناس إللي حريصة على تفيذ أمر رسول الله ﷺ وحتى وهو مش شايفهم زي أبو قتادة كده،\nولّا يتعجب من صبر كعب بن مالك وثباته في الابتلاء الشديد ده، وإنه مبعش دينه بعرض من الدنيا في حين إن في ناس بتبيع دينها حتى بدون عَرض من الدنيا ربنا يعافينا\nعدّى أربعين يوم على الوضع إللي كعب فيه ده، وفجأة رسول الله ﷺ يرسل رجل لكعب بن مالك يخبره رسالة،\nهل يا ترى الرسالة دي فيها الفرج ولّا زيادة في البلاء؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 227, "l": "الجزء 201 | كعب بن مالك الجزء الثالث", "u": "https://www.facebook.com/groups/710210019782034/permalink/836851950451173/", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائتين_وواحد\n#أحداث_السنة_التاسعة_من_الهجرة\n#كعب_بن_مالك_الجزء_الثالث\nوقفنا المرة إللي فاتت عند رسول الله ﷺ لما أرسل رجل لكعب بن مالك بعد أربعين يوم من مقاطعة المسلمين له عشان يخبره بخبر جديد،\nالخبر الجديد للأسف مكنش خبر الفرج والخروج من الأزمة ولكنه كان خبر لزيادة الابتلاء،\nقال الرجل لكعب بن مالك إن رسول الله ﷺ بيأمره إنه يعتزل امرأته،\nفكعب سأله: أُطَلِّقُهَا أَمْ مَاذَا أَفْعَلُ؟\nلأن كلمة اعتزال كان من معانيها عندهم الطلاق، فهو كان عايز يتأكد إذا كان يطلقها أو لأ،\nفَقالَ: لَا، بَلِ اعْتَزِلْهَا فَلَا تَقْرَبَنَّهَا.\nسبحان الله، كعب كان عنده استعداد يطلق زوجته لو كان جاء الأمر إنه يطلقها بدون أي تردد\nيعني هو معترضش نهائي على أمر رسول الله ﷺ، لكنه سأل عن معنى الاعتزال، هل المطلوب منه يطلقها ولّا يعمل إيه، وهينفذ على طول\nهو إيه أصلا إللي يخليه يستحمل الضغط ده كله\nفي ناس لما تتعرض لبعض البلاء متستحملش وتلاقيها اعترضت على ربنا ويسيبوا طريق ربنا خالص،\nلكن كعب عارف قيمة الدين إللي بينتمي له ده، وعارف إنه أخطأ فبيواجه خطأه ده\nفالصحابي قال له لا تطلقها ولكن متقربش منها،\nفقال كعب لزوجته:\n\" الْحَقِي بِأهْلِكِ فَكُونِي عِنْدَهُمْ حَتَّى يَقْضِيَ اللهُ في هَذَا الْأَمْرِ\"\nيعني قالها تروح تقعد عند أهلها لحد ما الموضوع ده ينتهي،\nوالأمر ده جاء للثلاثة الذين خُلفوا يعني مش لكعب بس،\nفزوجة هلال بن أمية راحت لرسول الله ﷺ وقالت له:\nيَا رَسُولَ اللهِ، إِنَّ هِلَالَ بْنَ أُمَيَّةَ شَيْخٌ ضَائِعٌ لَيْسَ لَهُ خَادِمٌ، فَهَلْ تَكْرَهُ أَنْ أَخْدُمَهُ؟ \nيعني هلال بن أمية كبير في السن ومفيش حد يخدمه، وهي عايزة تقعد معاه تخدمه فبتستأذن رسول الله ﷺ إنها تقعد معاه تخدمه وبتسأل إذا رسول الله ﷺ بيكره كده أو لأ،\nفقَالَ لها رسول الله ﷺ:لَا، وَلَكِنْ لَا يَقْرَبَنَّكِ\nيعني رسول الله ﷺ وافق إنها تقعد معاه تخدمه ولكن ميقربش منها،\nفَقَالَتْ:\n\"إِنَّهُ وَاللهِ مَا بِهِ مِنْ حَرَكَةٍ إِلَى شَيْءٍ، وَوَاللهِ مَا زَالَ يَبْكِي مُنْذُ كَانَ مِنْ أمْرِهِ مَا كَانَ إِلَى يَومِهِ هَذَا\"\nيعني هو فاقد الرغبة لكل حاجة في الدنيا من ساعة ما حصل إللي حصل ومش بيعمل حاجة غير البكاء لأنه خايف إن عمله يُحبط.\n☆ممكن حد يسأل ويقول طيب ماهو هلال بن أمية رجل كبير في السن يبقى أصلا معلهوش جهاد وبالتالي يكون من المعذورين\nلأ الموضوع مش كده،\nالجهاد كان فرض عين ولا يُعذر من يتخلف عن الجهاد إلا إللي ميقدرش أنه يجاهد،\nومش شرط كل المجاهدين إللي بيخرجوا في الجيش بيقاتلوا،\nممكن يكون في الساقة، يعني يسقي ويخدم ويداوي الجريح، \nأهم حاجة إنه ميكنش عنده مرض أو علة تمنعه من الخروج،\nفلو عنده سبب يمنعه من الخروج خلاص مش هيبقى في مشكلة أصلا،\nفهو مع إنه كان رجل كبير في السن إلا إنه كان صحيح معندوش مرض ولا عنده عذر يمنعه من الخروج للجهاد في سبيل الله\nالمهم،\nواحد من أقارب كعب بن مالك لما شاف إن رسول الله ﷺ أَذن لزوجة هلال بن أمية إنها تخدمه قال لكعب:\nلَوِ اسْتَأْذَنْتَ رَسُولَ اللهِ ﷺ فِي امْرَأَتِكَ، فَقَدْ أَذِن لِامْرَأَةِ هِلَالِ بْنِ أُمَيَّةَ أَنْ تَخْدُمَهُ\nيعني إيه رأيك تستأذن رسول الله ﷺ إنه يخلي زوجتك معاك تخدمك زي ما أَذن لزوجة هلال بن أمية،\nفقال كعب رضي الله عنه:\n\"لَا أَسْتَأذِنُ فِيهَا رَسُولَ اللهِ ﷺ وَمَا يُدْرِيني مَاذَا يقُولُ رَسُولُ\nاللهِ ﷺ إِذَا اسْتَأْذَنْتُهُ، وَأَنَا رَجُلٌ شَابٌ\"\nيعني رفض إنه يستأذن رسول الله ﷺ إن زوجته تفضل معاه تخدمه؛ لأنه مكنش عارف رد فعل رسول الله ﷺ هيكون إيه وهو رجل شاب ممكن ميقدرش يملك نفسه ويخالف أمر رسول الله ﷺ بإنه لا يقترب منها،\nواستمر الحال ده لحد ما كملوا خمسين ليلة من هجر المسلمين لهم،\nويُقال إن الخمسين ليلة دي هي نفس الوقت إللي رسول الله ﷺ قضاه في غزوة تبوك،\nيعني كإن انت كنت مستصعب تروح وترجع المسافة دي كلها وتبقى قاعد في مشقة،\nطيب انت قعدت أهه نفس الفترة متضايق وتعبان، \nبالعكس كمان ده انت لو كنت طلعت معاهم، على الأقل نفسيا مكنتش هتبقى مقهور ومخنوق كده،\nكعب بيتكلم عن نفسه وبيقول إنه وصل لمرحلة إن الأرض ضاقت عليه وضاقت عليه نفسه،\nواحنا ممكن نفكر إن الواحد ممكن يهوّل من حالته النفسية، لكن ربنا العالم بأحوال القلوب وصف حالتهم بإنهم فعلا ضاقت عليهم الأرض بما رحبت وضاقت عليهم أنفسهم،\nربنا بيقول في سورة التوبة:\n\"حَتَّىٰ إِذَا ضَاقَتْ عَلَيْهِمُ الْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوا أَن لَّا مَلْجَأَ مِنَ اللَّهِ إِلَّا إِلَيْهِ\"\nفهو وصل لحالة نفسية صعبة جدا والأمور لما بتضيق أوي كده يأتي الفرج بعدها على طول\nفي صباح الليلة الخمسين كعب صلى الفجر فوق سطح البيت، وقعد بعد الصلاة وهو مهموم مغموم على الحالة إللي ربنا ذكرها في الآية إللي قلناها من شوية《ضَاقَتْ عَلَيْهِمُ الْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ》،وهو قاعد على الحالة دي فجأة سمع واحد بيصرخ بأعلى صوته:\nيَا كَعْبَ بْنَ مَالِك، أبْشِرْ!!\nإيه إللي حصل \nلما رسول الله ﷺ صلى بالناس الصبح نزلت توبة كعب بن مالك فقال رسول الله ﷺ للناس إن ربنا تاب على الذين خُلّفوا:\nكعب بن مالك وهلال بن أمية ومُرارة بن الربيع،\nفالناس تسارعوا عشان يبشروهم بتوبة ربنا عليهم، فانطلق اتنين من الصحابة لبيت كعب، واحد على فرس والتاني على قدمه،\nفالماشي لما لقى إن إللي راكب على الفرس هيسبقه راح طالع على تَل عالي كده ونادى كعب بن مالك:\nيَا كَعْبَ بْنَ مَالِكٍ، أبْشِرْ!!\nفكان صوته أسرع من الرجل إللي كان على الفرس،\nفلما سمع كعب الصوت عرف إن الفرج جاء فراح نازل على الأرض ساجد لله شكرا،\nوجاء الرجل إللي نادى على كعب لبيته فخلع كعب الثوبين إللي كان لابسهم وأهداهم للرجل صاحب البشارة،\nواستعار كعب ثوبين تانيين عشان يقدر يخرج ويروح المسجد لرسول الله ﷺ،\nيعني هو مكنش عنده ملابس غير إللي كان لابسهم دول ومع ذلك خلعهم وأعطاهم للبشير،\nتوجه كعب بن مالك للمسجد، وهو ماشي الناس بتقابله وتهنيه وتقوله:\n\"لِتَهْنِكَ تَوْبَةُ اللهُ عَلَيْكَ\"\nيعني بيقولوا له هنيئا لك توبة الله عليك، وإللي كانوا بيهنوه هم الأنصار،\nلما دخل كعب المسجد لقى رسول الله ﷺ قاعد والصحابة حوله فقام طلحة بن عبيد الله رضي الله عنه من بين الناس يهنئ كعب،\nيقول كعب بن مالك:\n\"قَامَ طَلْحَةُ بْنُ عُبَيْدِ اللهِ يُهَرْوِلُ حَتَّى صَافَحَنِي وَهَنَّأَنِي، وَاللهِ مَا قَامَ رَجُلٌ مِنَ المُهَاجِرِينَ غَيرُهُ\"\nيعني طلحة أول ما شاف كعب قام يجري يسلم عليه ويهنئه\nكأنه عايز يقول له والله ما منعني عن مواساتك ودعمك إلا إني ألتزم أمر النبي ﷺ،\nوكان طلحة من المهاجرين وكعب من الأنصار، فَكَانَ كَعْبٌ لَا يَنْسَاهَا لِطَلْحَةَ، وخصوصا إن محدش من المهاجرين قام غير طلحة\n☆طيب ليه محدش من المهاجرين قام يهنئ كعب رضي الله عنه\nشوفوا،\nالمهاجرين ضحوا تضحية كبيرة جدا، تركوا ديارهم وأموالهم وتعرضوا لأذى كبير جدا خلال ثلاثة عشرة عام،\nفهم زعلانين ومش مستوعبين ومش قادرين يتقبلوا إزاي يعني واحد يتخلف عن غزوة عشان شوية ثمار مستنيها\nهو كده دايما صاحب الابتلاء العالي أو صاحب التضحية الأكبر لما يلاقي واحد وقع في حاجة بالنسبة له بسيطة مش بيبقى متقبل الموضوع وشايف إن الشخص إللي قصاده ده زي ما بنقول بيدلع\nعارفين مثلا زي واحد بيحفظ جزء من القرآن كل يوم، \nوواحد تاني بيحفظ خمس آيات، \nفييجي إللي بيحفظ خمس آيات ده ويقول معلش أنا محفظتش النهاردة سامحني أصل الحفظ كان صعب عليّ،\nتخيلوا إللي بيحفظ جزء ده هيبقى إحساسه إيه ولّا هيرد عليه بإيه\nعشان كده احنا محتاجين يبقى عندنا توازن في الفهم،\nأيوة أنا ممكن أكون ضحيت تضحية كبيرة أو تعرضت لابتلاء أكثر من غيري لكن مش معنى كده إن الشخص التاني ابتلاءه أو تضحيته بسيطة أو إني استصغر إللي عمله،\nلازم أفهم إن كل واحد له قدرته وله المكان المناسب بتاعه\nالمهم،\nكعب رضي الله عنه اقترب من رسول الله ﷺ و سلّم عليه، يقول كعب:\nفَلَمَّا سَلَّمْتُ عَلَى رَسُولِ اللهِ ﷺ قَالَ وَهُوَ يَبْرُقُ وَجْهُهُ مِنَ السُّرُورِ:\n\"أَبْشِرْ بِخَيْرِ يَوْمٍ مَرَّ عَلَيْكَ مُذْ وَلَدَتْكَ أُمُّكَ\"\nيعني رسول الله ﷺ كان فرحان جدا لكعب لدرجة إن وجهه ﷺ كان بيلمع من الفرح، وَكَانَ رَسُولُ اللهِ ﷺ إِذَا سُرَّ اسْتَنَارَ وَجْهُهُ حَتَّى كَأَنَّ وَجْهَهُ قِطْعَةُ قَمَرٍ،\nيعني رسول الله ﷺ لما كان بيبقى مبسوط وشه بينور كأنه فلقة قمر زي ما بنقول بالعامية كده\nوكان الصحابة بيعرفوا ده من رسول الله ﷺ، يعني لما يكونوا عايزين يعرفوا رسول الله ﷺ مبسوط ولّا لأ ينظروا لوجهه ويعرفوا على طول، ﷺ \nفرسول الله ﷺ بشّر كعب رضي الله عنه بتوبة ربنا عليه\nوقال له إن اليوم ده هو أحسن يوم مر على كعب في حياته في حياته لأن ربنا تاب عليه،\nطبعا أحسن يوم في حياته على الأطلاق هو يوم دخوله للإسلام لأنه كده ربنا أعتقه من النار،\nلكن اليوم إللي ربنا تاب عليه ده أحسن يوم في حياته من بعد دخوله للإسلام،\nفلما كعب قعد قصاد رسول الله ﷺ بين يديه، قال له كعب:\n\"يَا رَسُولَ اللهِ، إِنَّ مِنْ تَوْبَتِي أَنْ أنْخَلِعَ مِنْ مَالِي صَدَقَةً إِلَى اللهِ وَإِلَى رَسُولِهِ\"\nيعني هو كان عايز يتصدق بماله كله في سبيل الله،\nوالواحد في أوقات الفرح ممكن ياخد قرارات يندم عليها بعدين\nعشان كده مينفعش ناخد قرار في وقت الغضب أو في وقت الفرح، \nلكن يكون في توازن، وهو ده إللي رسول الله ﷺ قاله لكعب:\n قَالَ رَسُولُ اللهِ ﷺ: \nأَمْسِكَ عَلَيْكَ بَعْضَ مَالِكَ فَهُوَ خَيْرٌ لَكَ\nيعني كويس إنك تتصدق لكن مش تتصدق بكل مالك لأن انت عندك مسؤوليات تانية هتحتاج فيها للمال ده زي إنه يصرف على نفسه وعياله،\nفقال كعب: \"إِنِّي أُمْسِكُ سَهْمِي الَّذِي بِخَيْبَرَ\"\nيعني هو له نصيب في خيبر هيخليه ويتصدق بالباقي.\nوكمل كعب كلامه مع رسول الله ﷺ قال:\nيَا رَسُولَ اللهِ، إِنَّ اللهَ تَعَالَى إِنَّمَا أنْجَانِي بِالصِّدْقِ، وَإِنَّ مِنْ تَوْبَتِي أَنْ لَا أُحَدِّثَ إِلَّا صِدْقًا مَا بَقِيتُ\nيعني على الرغم من كل الابتلاءات إللي مر بيها كعب دي إلا إن إللي نجاه في النهاية هو صدقه مع رسول الله ﷺ،\nوإنه لم يكذب زي المنافقين إللي جاءوا وكذبوا على رسول الله ﷺ،\nوفعلا الصدق هو إللي بينجي صاحبه، أيوة الكذب ممكن ينجي صاحبه في البداية لكن في النهاية حبل الكذب قصير ولازم في يوم من الأيام هينكشف الكذب ده وهتبقى العواقب شديدة،\nلكن ربنا بينجي الصادق حتى لو تعرض للابتلاء والأذى في البداية،\nولأن كعب التزم الصدق من البداية كانت نهايته إن ربنا أنزل توبته في قرآن يُتلى إلى يوم القيامة\nربنا قال في سورة التوبة:\n\" لَّقَد تَّابَ اللَّهُ عَلَى النَّبِيِّ وَالْمُهَاجِرِينَ وَالْأَنصَارِ الَّذِينَ اتَّبَعُوهُ فِي سَاعَةِ الْعُسْرَةِ مِن بَعْدِ مَا كَادَ يَزِيغُ قُلُوبُ فَرِيقٍ مِّنْهُمْ ثُمَّ تَابَ عَلَيْهِمْ ۚ إِنَّهُ بِهِمْ رَءُوفٌ رَّحِيمٌ ۩ \nوَعَلَى الثَّلَاثَةِ الَّذِينَ خُلِّفُوا حَتَّىٰ إِذَا ضَاقَتْ عَلَيْهِمُ الْأَرْضُ بِمَا رَحُبَتْ وَضَاقَتْ عَلَيْهِمْ أَنفُسُهُمْ وَظَنُّوا أَن لَّا مَلْجَأَ مِنَ اللَّهِ إِلَّا إِلَيْهِ ثُمَّ تَابَ عَلَيْهِمْ لِيَتُوبُوا ۚ إِنَّ اللَّهَ هُوَ التَّوَّابُ الرَّحِيمُ\"\n☆لو تاخدوا بالكم هتلاقوا إن آية توبة الثلاثة الذين خُلفوا جاءت معطوفة على آية توبة النبي والمهاجرين والأنصار،\nعشان ربنا يعرفنا إن التوبة دي شرف وحاجة عظيمة جدا دخل فيها رسول الله ﷺ والمهاجرين والأنصار، وإنها مش حاجة وحشة،\nبعكس لو كانت الآية إللي فيها توبتهم جت كده لوحدها كان الناس ممكن يحسوا بالنقص تجاه الثلاثة الذين خُلّفوا\nكعب بن مالك أخطأ يا جماعة، صح؟\nلكنه واجه الخطأ وتحمل نتيجة خطأه،\nفي ناس بتغلط ومش عايزة تدفع تمن خطأها ولا تواجه النتائج المترتبة على خطأها ده،\nوعايزين الدنيا تبقى وردي ومفيش أي مشاكل وتعيش حياتها طبيعية، وعادي يا جماعة خلاص مش هعمل كده تاني وفضّونا من السيرة دي بقى\n برغم إن غلطهم ساعات بيكون خطأ كبير جدا\nوطبعا إللي عايزينه ده مستحيل\nفالنوعية دي من الناس للأسف بتبدأ تعالج الخطأ بخطأ أكبر، زي مثلا موقف كعب لما جاءته رسالة من ملك غسّان،\nلو كعب بن مالك رضي الله عنه مكنش واجه خطأه صح كان هياخد الموضوع فرصة ويقول خلاص بقى أنا هروح للي يقدرني ويعرف مكانتي، وانتم السبب في كده\nمانتم بتعاملوني وحش، وفين بقى لا تُعن الشيطان على أخيك،\nأنا أه غلطت، لكن المفروض انكم تحتوُوني مش تنفروني كده، وخلاص يعني ماهي غزوة وعدت، وأنا حضرت كل الغزوات إللي فاتت مجتش على دي، انتم عاملين ده كله ليه، أنا معملتش كبيرة من الكبائر يعني\nساعتها بقى كان هيخسر باقي عمره، لكنه كان عارف إن ده من البلاء،\nوعارف إن علاج الخطأ هو مواجهة الخطأ ده، وإللي بيهرب من المواجهة هيفضل ندمان طول عمره\nفاحنا كمان محتاجين نفهم الكلام ده،\nلما واحد فينا يكون ناوي يمشي في طريق ربنا ويطيع أوامره ويقابل أي نوع من أنواع الابتلاء ويلاقي معاملة سيئة مثلا أو جفاء أو سخرية من أي حد وخصوصا لو حد من الناس إللي ظاهره الصلاح؛ يفهم على طول إن ده من البلاء والفتنة،\nهل هيصبر زي كعب بن مالك ولّا هيقع ويرجع عن طريق ربنا\nعارفين مين إللي حكى قصة كعب بن مالك؟\nإللي حكى قصة كعب بن مالك دي هو ابن كعب بن مالك نفسه،\nيعني كعب كِبر في السن جدا لحد ما بقى أعمى وكان لسه فاكر القصة إللي حصلت معاه وبيعلمها لابنه كمان بالتفصيل إللي قلناه ده،\nبيعلم ابنه وبيعلمنا احنا كمان عشان منقعش في نفس الخطأ، \nبيعلمه وهو مش متضايق ولا مكسوف ولا خايف صورته تتهز قصاد ابنه ولا قصاد حد، همه إنه يعلم الناس الخير\n♡قصة كعب بن مالك مليانة دروس وعبر كتير،\nوأنا حاولت على أد ما اقدر أوضح لكم الدروس دي،\nوفي التعليقات هتلاقوا روابط للمصادر إللي قلت منها القصة،\nياريت تقرأوا وتسمعوا هتستفيدوا كتير إن شاء الله \nوبكده انتهت قصة توبة كعب بن مالك رضي الله عنه.\nبعد ما رسول الله ﷺ كان رجع من غزوة تبوك قبل حكاية كعب بن مالك دي عمل حاجة عجيبة جدا،\nرسول الله ﷺ حرق مسجد اتبني جديد في المدينة\nإيه قصة المسجد ده، وليه رسول الله ﷺ حرقه؟\nده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
